+++ b/js/delivery-notes-crypto.js
@@ -0,0 +1,186 @@
+// Encrypted delivery notes: hybrid post-quantum public-key encryption in the browser.
+//
+// Construction (HPKE-style, single-shot):
+//   1. KEM:  X-Wing (X25519 + ML-KEM-768) encapsulates a fresh 32-byte shared secret
+//            to the store's fulfillment public key. The shared secret stays safe as long
+//            as EITHER X25519 or ML-KEM-768 remains unbroken.
+//   2. KDF:  HKDF-SHA-256(ikm = shared secret, salt = SHA-256(recipient public key),
+//            info = INFO_LABEL) -> AES-256-GCM key, bound to the exact recipient key.
+//   3. AEAD: AES-256-GCM over the length-padded note, with the envelope header
+//            (version, suite, key id, note id, KEM ciphertext) as associated data, so
+//            any tampering with the header or ciphertext fails authentication.
+//
+// Every note gets a fresh encapsulation, so each AES key encrypts exactly one message.
+
+import { xwing } from '../vendor/noble-xwing.js';
+
+export const VERSION = 1;
+export const SUITE = 'XWING768-HKDF-SHA256-AES256GCM';
+export const KEM_ALG = 'X-Wing';
+export const MAX_NOTE_BYTES = 1024;
+
+const INFO_LABEL = 'daily-grind/delivery-notes/v1';
+const PAD_BLOCK = 256;
+const NONCE_BYTES = 12;
+const NOTE_ID_BYTES = 16;
+const KID_PATTERN = /^[A-Za-z0-9._-]{1,64}$/;
+
+const subtle = globalThis.crypto?.subtle;
+const encoder = new TextEncoder();
+
+export function isSupported() {
+  return Boolean(subtle && globalThis.crypto.getRandomValues && globalThis.isSecureContext !== false);
+}
+
+// --- encoding helpers -------------------------------------------------------
+
+export function toBase64Url(bytes) {
+  let bin = '';
+  for (const b of bytes) bin += String.fromCharCode(b);
+  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function fromBase64Url(str, expectedLength) {
+  if (typeof str !== 'string' || !/^[A-Za-z0-9_-]*$/.test(str)) {
+    throw new TypeError('Invalid base64url data');
+  }
+  const bin = atob(str.replace(/-/g, '+').replace(/_/g, '/') + '='.repeat((4 - (str.length % 4)) % 4));
+  const out = Uint8Array.from(bin, (c) => c.charCodeAt(0));
+  if (expectedLength !== undefined && out.length !== expectedLength) {
+    throw new RangeError(`Expected ${expectedLength} bytes, got ${out.length}`);
+  }
+  return out;
+}
+
+function randomBytes(n) {
+  return globalThis.crypto.getRandomValues(new Uint8Array(n));
+}
+
+async function sha256(bytes) {
+  return new Uint8Array(await subtle.digest('SHA-256', bytes));
+}
+
+// Deterministic encoding of the authenticated header (field order is fixed).
+function headerBytes({ v, suite, kid, noteId, enc }) {
+  return encoder.encode(JSON.stringify([v, suite, kid, noteId, enc]));
+}
+
+// Pad to a multiple of PAD_BLOCK so ciphertext length only reveals a coarse size bucket.
+function pad(noteBytes) {
+  const total = Math.ceil((noteBytes.length + 2) / PAD_BLOCK) * PAD_BLOCK;
+  const out = new Uint8Array(total);
+  out[0] = noteBytes.length >>> 8;
+  out[1] = noteBytes.length & 0xff;
+  out.set(noteBytes, 2);
+  return out;
+}
+
+function unpad(padded) {
+  const len = (padded[0] << 8) | padded[1];
+  if (len > MAX_NOTE_BYTES || len + 2 > padded.length || padded.length % PAD_BLOCK !== 0) {
+    throw new Error('Malformed note padding');
+  }
+  return padded.subarray(2, 2 + len);
+}
+
+async function deriveAeadKey(sharedSecret, recipientPublicKey, usage) {
+  const ikm = await subtle.importKey('raw', sharedSecret, 'HKDF', false, ['deriveKey']);
+  return subtle.deriveKey(
+    { name: 'HKDF', hash: 'SHA-256', salt: await sha256(recipientPublicKey), info: encoder.encode(INFO_LABEL) },
+    ikm,
+    { name: 'AES-GCM', length: 256 },
+    false,
+    [usage],
+  );
+}
+
+// --- recipient keys ---------------------------------------------------------
+
+// Short, human-comparable fingerprint of a recipient public key.
+export async function fingerprint(publicKey) {
+  const digest = await sha256(publicKey);
+  const hex = Array.from(digest.subarray(0, 16), (b) => b.toString(16).padStart(2, '0')).join('');
+  return hex.toUpperCase().match(/.{4}/g).join(' ');
+}
+
+// Validates a published recipient key document: { kid, alg: "X-Wing", publicKey: <base64url> }.
+export function parseRecipientKey(doc) {
+  if (!doc || typeof doc !== 'object') throw new TypeError('Key document must be an object');
+  if (doc.alg !== KEM_ALG) throw new Error(`Unsupported key algorithm: ${doc.alg}`);
+  if (typeof doc.kid !== 'string' || !KID_PATTERN.test(doc.kid)) throw new Error('Invalid key id');
+  return { kid: doc.kid, publicKey: fromBase64Url(doc.publicKey, xwing.lengths.publicKey) };
+}
+
+export function generateRecipientKeyPair(kid) {
+  const { publicKey, secretKey } = xwing.keygen();
+  return { kid, publicKey, secretKey };
+}
+
+// --- seal / open ------------------------------------------------------------
+
+export async function sealNote(note, recipient) {
+  const noteBytes = encoder.encode(note);
+  if (noteBytes.length === 0) throw new RangeError('Note is empty');
+  if (noteBytes.length > MAX_NOTE_BYTES) throw new RangeError(`Note exceeds ${MAX_NOTE_BYTES} bytes`);
+
+  const { cipherText, sharedSecret } = xwing.encapsulate(recipient.publicKey);
+  const header = {
+    v: VERSION,
+    suite: SUITE,
+    kid: recipient.kid,
+    noteId: toBase64Url(randomBytes(NOTE_ID_BYTES)),
+    enc: toBase64Url(cipherText),
+  };
+  const padded = pad(noteBytes);
+  try {
+    const key = await deriveAeadKey(sharedSecret, recipient.publicKey, 'encrypt');
+    const nonce = randomBytes(NONCE_BYTES);
+    const ct = await subtle.encrypt(
+      { name: 'AES-GCM', iv: nonce, additionalData: headerBytes(header), tagLength: 128 },
+      key,
+      padded,
+    );
+    return { ...header, nonce: toBase64Url(nonce), ct: toBase64Url(new Uint8Array(ct)) };
+  } finally {
+    sharedSecret.fill(0);
+    noteBytes.fill(0);
+    padded.fill(0);
+  }
+}
+
+// Recipient side (normally runs in the store's fulfillment system, not the customer's browser).
+export async function openNote(envelope, recipient) {
+  if (!envelope || envelope.v !== VERSION || envelope.suite !== SUITE) {
+    throw new Error('Unsupported envelope version or suite');
+  }
+  if (envelope.kid !== recipient.kid) throw new Error('Envelope was sealed to a different key');
+
+  const header = {
+    v: envelope.v,
+    suite: envelope.suite,
+    kid: envelope.kid,
+    noteId: envelope.noteId,
+    enc: envelope.enc,
+  };
+  fromBase64Url(header.noteId, NOTE_ID_BYTES);
+  const cipherText = fromBase64Url(header.enc, xwing.lengths.cipherText);
+  const nonce = fromBase64Url(envelope.nonce, NONCE_BYTES);
+  const ct = fromBase64Url(envelope.ct);
+
+  const sharedSecret = xwing.decapsulate(cipherText, recipient.secretKey);
+  try {
+    const key = await deriveAeadKey(sharedSecret, recipient.publicKey, 'decrypt');
+    const padded = new Uint8Array(
+      await subtle.decrypt(
+        { name: 'AES-GCM', iv: nonce, additionalData: headerBytes(header), tagLength: 128 },
+        key,
+        ct,
+      ),
+    );
+    const note = new TextDecoder('utf-8', { fatal: true }).decode(unpad(padded));
+    padded.fill(0);
+    return note;
+  } finally {
+    sharedSecret.fill(0);
+  }
+}
