new file mode 100644
index 0000000..293943f
--- /dev/null
+++ b/js/delivery-notes.js
@@ -0,0 +1,131 @@
+// Homepage UI for encrypted delivery notes. Plaintext never leaves this page:
+// only the sealed envelope is kept (in sessionStorage) for checkout to submit.
+
+import {
+  isSupported, sealNote, openNote, parseRecipientKey, generateRecipientKeyPair, fingerprint, toBase64Url,
+  MAX_NOTE_BYTES,
+} from './delivery-notes-crypto.js';
+
+const KEY_URL = '/.well-known/daily-grind/delivery-notes-key.json';
+const STORAGE_KEY = 'dailyGrind.pendingDeliveryNote';
+
+const $ = (id) => document.getElementById(id);
+const form = $('dn-form');
+const input = $('dn-input');
+const counter = $('dn-counter');
+const sealBtn = $('dn-seal');
+const status = $('dn-status');
+const keyInfo = $('dn-key');
+const output = $('dn-output');
+const envelopeView = $('dn-envelope');
+const openBtn = $('dn-open');
+const discardBtn = $('dn-discard');
+
+const encoder = new TextEncoder();
+let recipient = null;
+let demoMode = false;
+
+function setStatus(message, kind = 'info') {
+  status.textContent = message;
+  status.dataset.kind = kind;
+}
+
+function updateCounter() {
+  const used = encoder.encode(input.value).length;
+  counter.textContent = `${used} / ${MAX_NOTE_BYTES} bytes`;
+  counter.dataset.over = String(used > MAX_NOTE_BYTES);
+  sealBtn.disabled = !recipient || used === 0 || used > MAX_NOTE_BYTES;
+}
+
+async function loadRecipientKey() {
+  try {
+    const res = await fetch(KEY_URL, { cache: 'no-store', credentials: 'omit' });
+    if (!res.ok) throw new Error(`HTTP ${res.status}`);
+    return { key: parseRecipientKey(await res.json()), demo: false };
+  } catch (err) {
+    // No published store key (e.g. static preview): fall back to a throwaway key pair
+    // generated in this tab so the full flow can be exercised end to end.
+    console.info('Delivery notes: store key unavailable, using demo key.', err);
+    const kid = `demo-${toBase64Url(crypto.getRandomValues(new Uint8Array(6)))}`;
+    return { key: generateRecipientKeyPair(kid), demo: true };
+  }
+}
+
+function showEnvelope(envelope) {
+  envelopeView.value = JSON.stringify(envelope, null, 2);
+  output.hidden = false;
+  openBtn.hidden = !demoMode;
+}
+
+function clearEnvelope() {
+  sessionStorage.removeItem(STORAGE_KEY);
+  envelopeView.value = '';
+  output.hidden = true;
+}
+
+form.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  if (sealBtn.disabled) return;
+  sealBtn.disabled = true;
+  setStatus('Encrypting…');
+  try {
+    const envelope = await sealNote(input.value, recipient);
+    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(envelope));
+    input.value = '';
+    showEnvelope(envelope);
+    setStatus('Note encrypted and attached to your next order. The plaintext has been cleared.', 'ok');
+  } catch (err) {
+    setStatus(`Could not encrypt note: ${err.message}`, 'error');
+  } finally {
+    updateCounter();
+  }
+});
+
+openBtn.addEventListener('click', async () => {
+  try {
+    const note = await openNote(JSON.parse(envelopeView.value), recipient);
+    setStatus(`Store-side decryption (demo) succeeded: “${note}”`, 'ok');
+  } catch (err) {
+    setStatus(`Decryption failed — envelope rejected: ${err.message}`, 'error');
+  }
+});
+
+discardBtn.addEventListener('click', () => {
+  clearEnvelope();
+  setStatus('Encrypted note discarded.');
+});
+
+input.addEventListener('input', updateCounter);
+
+async function init() {
+  if (!isSupported()) {
+    setStatus('Encrypted notes need a secure (HTTPS) connection and a modern browser.', 'error');
+    input.disabled = true;
+    sealBtn.disabled = true;
+    return;
+  }
+  setStatus('Fetching the store’s public key…');
+  const { key, demo } = await loadRecipientKey();
+  recipient = key;
+  demoMode = demo;
+  keyInfo.textContent = `${demo ? 'Demo key (generated in this tab)' : 'Store key'} ${key.kid} · fingerprint ${await fingerprint(key.publicKey)}`;
+  keyInfo.dataset.demo = String(demo);
+
+  const pending = sessionStorage.getItem(STORAGE_KEY);
+  if (pending) {
+    try {
+      const envelope = JSON.parse(pending);
+      if (envelope.kid !== key.kid) throw new Error('stale key');
+      showEnvelope(envelope);
+      setStatus('An encrypted note is already attached to your next order.', 'ok');
+    } catch {
+      clearEnvelope();
+      setStatus('Ready. Your note is encrypted on this device before it goes anywhere.');
+    }
+  } else {
+    setStatus('Ready. Your note is encrypted on this device before it goes anywhere.');
+  }
+  updateCounter();
+}
+
+init();
