@@ -0,0 +1,58 @@
+// Round-trip and tamper tests for js/delivery-notes-crypto.js (run: pnpm test).
+import assert from 'node:assert/strict';
+import { test } from 'node:test';
+import {
+  sealNote, openNote, generateRecipientKeyPair, parseRecipientKey, toBase64Url, fingerprint, MAX_NOTE_BYTES,
+} from '../js/delivery-notes-crypto.js';
+
+const store = generateRecipientKeyPair('store-2026-11');
+const note = 'Gate code 4412 — leave at side door, dog is friendly 🐕';
+
+test('seal/open round trip', async () => {
+  const env = await sealNote(note, store);
+  assert.equal(await openNote(env, store), note);
+  assert.ok(!JSON.stringify(env).includes('4412'));
+});
+
+test('fresh encapsulation per note', async () => {
+  const [a, b] = await Promise.all([sealNote(note, store), sealNote(note, store)]);
+  assert.notEqual(a.enc, b.enc);
+  assert.notEqual(a.ct, b.ct);
+});
+
+test('length is padded to 256-byte buckets', async () => {
+  const short = await sealNote('a', store);
+  const longer = await sealNote('a'.repeat(200), store);
+  assert.equal(short.ct.length, longer.ct.length);
+});
+
+test('tampering with any authenticated field fails', async () => {
+  const env = await sealNote(note, store);
+  const flip = (s) => (s[5] === 'A' ? s.slice(0, 5) + 'B' + s.slice(6) : s.slice(0, 5) + 'A' + s.slice(6));
+  for (const field of ['noteId', 'enc', 'nonce', 'ct']) {
+    await assert.rejects(openNote({ ...env, [field]: flip(env[field]) }, store), `field ${field}`);
+  }
+  await assert.rejects(openNote({ ...env, v: 2 }, store));
+  await assert.rejects(openNote({ ...env, kid: 'other' }, store));
+});
+
+test('wrong recipient cannot open', async () => {
+  const env = await sealNote(note, store);
+  const other = generateRecipientKeyPair('store-2026-11');
+  await assert.rejects(openNote(env, other));
+});
+
+test('rejects empty and oversized notes', async () => {
+  await assert.rejects(sealNote('', store), RangeError);
+  await assert.rejects(sealNote('x'.repeat(MAX_NOTE_BYTES + 1), store), RangeError);
+  assert.equal(await openNote(await sealNote('x'.repeat(MAX_NOTE_BYTES), store), store), 'x'.repeat(MAX_NOTE_BYTES));
+});
+
+test('parseRecipientKey validates documents', async () => {
+  const doc = { kid: store.kid, alg: 'X-Wing', publicKey: toBase64Url(store.publicKey) };
+  assert.deepEqual(parseRecipientKey(doc).publicKey, store.publicKey);
+  assert.throws(() => parseRecipientKey({ ...doc, alg: 'X25519' }));
+  assert.throws(() => parseRecipientKey({ ...doc, kid: 'bad kid!' }));
+  assert.throws(() => parseRecipientKey({ ...doc, publicKey: doc.publicKey.slice(0, -4) }));
+  assert.match(await fingerprint(store.publicKey), /^([0-9A-F]{4} ){7}[0-9A-F]{4}$/);
+});
