index 66c9173..a2873b8 100644
--- a/index.html
+++ b/index.html
@@ -4,14 +4,102 @@
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <meta name="color-scheme" content="light dark">
   <title>The Daily Grind | Artisanal Coffee</title>
   <style>
     :root {
-      --primary: #4e342e;
-      --secondary: #d7ccc8;
+      color-scheme: light dark;
+
+      /* Brand */
+      --coffee: #4e342e;
+      --espresso: #3e2723;
+      --latte: #d7ccc8;
       --accent: #ffab40;
-      --text: #3e2723;
-      --light: #fafafa;
+
+      /* Raw light/dark values */
+      --bg-light: #faf6f2;
+      --bg-dark: #1a1310;
+      --surface-light: #ffffff;
+      --surface-dark: #271d19;
+      --text-light: #2b1d17;
+      --text-dark: #f3ebe5;
+      --muted-light: #6d5a50;
+      --muted-dark: #c2b0a5;
+      --heading-light: var(--coffee);
+      --heading-dark: #e6c9b5;
+      --border-light: #e6dbd2;
+      --border-dark: #3d2e28;
+      --btn-bg-light: var(--coffee);
+      --btn-bg-dark: #d9b49b;
+      --btn-hover-light: var(--espresso);
+      --btn-hover-dark: #e8cbb8;
+      --btn-text-light: #ffffff;
+      --btn-text-dark: #1a1310;
+      --nav-bg-light: var(--coffee);
+      --nav-bg-dark: #2e211c;
+      --footer-bg-light: #efe5dd;
+      --footer-bg-dark: #120d0b;
+      --soldout-bg-light: #ece4df;
+      --soldout-bg-dark: #3d2e28;
+      --soldout-text-light: #5d4037;
+      --soldout-text-dark: #e0d4cd;
+      --shadow-light: rgba(62, 39, 35, 0.12);
+      --shadow-dark: rgba(0, 0, 0, 0.45);
+
+      /* Active tokens (fallback for browsers without light-dark()) */
+      --bg: var(--bg-light);
+      --surface: var(--surface-light);
+      --text: var(--text-light);
+      --muted: var(--muted-light);
+      --heading: var(--heading-light);
+      --border: var(--border-light);
+      --btn-bg: var(--btn-bg-light);
+      --btn-hover: var(--btn-hover-light);
+      --btn-text: var(--btn-text-light);
+      --nav-bg: var(--nav-bg-light);
+      --footer-bg: var(--footer-bg-light);
+      --soldout-bg: var(--soldout-bg-light);
+      --soldout-text: var(--soldout-text-light);
+      --shadow: var(--shadow-light);
+    }
+
+    @media (prefers-color-scheme: dark) {
+      :root {
+        --bg: var(--bg-dark);
+        --surface: var(--surface-dark);
+        --text: var(--text-dark);
+        --muted: var(--muted-dark);
+        --heading: var(--heading-dark);
+        --border: var(--border-dark);
+        --btn-bg: var(--btn-bg-dark);
+        --btn-hover: var(--btn-hover-dark);
+        --btn-text: var(--btn-text-dark);
+        --nav-bg: var(--nav-bg-dark);
+        --footer-bg: var(--footer-bg-dark);
+        --soldout-bg: var(--soldout-bg-dark);
