+.hero--locations {
+  background-image: linear-gradient(rgba(0, 0, 0, 0.5), rgba(0, 0, 0, 0.5)),
+    url('https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?auto=format&fit=crop&w=1350&q=80');
+}
+
+.price {
+  display: block;
+  font-weight: bold;
+  color: var(--accent);
+  margin-top: 8px;
+}
+
+/* ---------- Cross-document view transitions ---------- */
+@view-transition {
+  navigation: auto;
+}
+
+nav {
+  view-transition-name: site-nav;
+}
+
+.logo {
+  view-transition-name: site-logo;
+}
+
+.hero {
+  view-transition-name: hero;
+}
+
+.hero h1 {
+  view-transition-name: hero-title;
+}
+
+.page-content {
+  view-transition-name: page-content;
+}
+
+/* Nav stays put; the hero morphs between pages; main content slides/fades. */
+::view-transition-group(site-nav),
+::view-transition-group(site-logo) {
+  animation: none;
+}
+
+::view-transition-group(hero),
+::view-transition-group(hero-title) {
+  animation-duration: 0.4s;
+  animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
+}
+
+::view-transition-old(page-content) {
+  animation: 0.2s ease-in both vt-fade-out;
+}
+
+::view-transition-new(page-content) {
+  animation: 0.3s ease-out 0.1s both vt-slide-in;
+}
+
+@keyframes vt-fade-out {
+  to { opacity: 0; }
+}
+
+@keyframes vt-slide-in {
+  from { opacity: 0; transform: translateY(16px); }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  @view-transition {
+    navigation: none;
+  }
+}
