+#!/usr/bin/env bash
+# Compiles smallpt to an ES module + .wasm in public/smallpt/. Requires Emscripten (em++).
+# (No -flto: this is a single translation unit, so LTO gains nothing.)
+set -euo pipefail
+cd "$(dirname "$0")"
+mkdir -p ../public/smallpt
+em++ -c smallpt.cpp -o smallpt.o -O3 -Werror -Wall
+em++ smallpt.o -o ../public/smallpt/smallpt.js \
+  -O3 \
+  -sSTRICT \
+  -sEXPORT_ES6 \
+  -sENVIRONMENT=worker \
+  -sALLOW_MEMORY_GROWTH \
+  -sSTACK_SIZE=1MB \
+  -sEXPORTED_FUNCTIONS=_render_rows,_sphere_count,_set_sphere_color,_malloc,_free \
+  -sEXPORTED_RUNTIME_METHODS=HEAPU8
+rm smallpt.o
