index 0000000..8cb1e97
--- /dev/null
+++ b/js/receipts-ui.js
@@ -0,0 +1,462 @@
+// Homepage UI for signing and verifying receipts and gift vouchers.
+// All untrusted text (pasted tokens, imported keys) is rendered with
+// textContent only — never innerHTML.
+
+import {
+  ALGORITHMS,
+  generateSigningKey,
+  isAlgorithmSupported,
+  signDocument,
+  verifyToken,
+  parseToken,
+  exportPublicKey,
+  importPublicKey,
+  toBase64Url,
+  fromBase64Url,
+} from './signing.js';
+import {
+  saveSigningKey,
+  loadSigningKey,
+  deleteSigningKey,
+  loadTrustedKeys,
+  addTrustedKey,
+  removeTrustedKey,
+} from './keystore.js';
+
+const MENU = [
+  { name: 'Maple Oat Latte', unitCents: 575 },
+  { name: 'Dark Roast Espresso', unitCents: 350 },
+  { name: 'Cold Brew', unitCents: 495 },
+  { name: 'Butter Croissant', unitCents: 325 },
+];
+const TAX_RATE_BPS = 825; // 8.25%
+const SHOP_NAME = 'The Daily Grind';
+
+const $ = (id) => document.getElementById(id);
+const money = (cents) => '$' + (cents / 100).toFixed(2);
+
+let signingKey = null;
+let trustedKeys = [];
+
+function el(tag, props = {}, children = []) {
+  const node = document.createElement(tag);
+  for (const [k, v] of Object.entries(props)) {
+    if (k === 'class') node.className = v;
+    else if (k === 'text') node.textContent = v;
+    else node.setAttribute(k, v);
+  }
+  for (const c of [].concat(children)) node.append(c);
+  return node;
+}
+
+function flash(target, message, isError = false) {
+  target.textContent = message;
+  target.classList.toggle('sig-error', isError);
+}
+
+async function copyText(text, statusEl) {
+  try {
+    await navigator.clipboard.writeText(text);
+    flash(statusEl, 'Copied to clipboard.');
+  } catch {
+    flash(statusEl, 'Copy failed — select the text and copy it manually.', true);
+  }
+}
+
+function download(filename, text) {
+  const url = URL.createObjectURL(new Blob([text], { type: 'text/plain' }));
+  const a = el('a', { href: url, download: filename });
+  document.body.append(a);
+  a.click();
+  a.remove();
+  URL.revokeObjectURL(url);
+}
+
+function randomCode(groups = 3) {
+  const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
+  const bytes = crypto.getRandomValues(new Uint8Array(groups * 4));
+  const chars = Array.from(bytes, (b) => alphabet[b & 31]);
+  return Array.from({ length: groups }, (_, i) => chars.slice(i * 4, i * 4 + 4).join('')).join('-');
+}
+
+// ---------- signing key panel ----------
+
+async function initAlgorithmSelect() {
+  const select = $('sig-alg');
+  for (const [alg, spec] of Object.entries(ALGORITHMS)) {
+    const supported = await isAlgorithmSupported(alg);
+    const opt = el('option', { value: alg, text: spec.label + (supported ? '' : ' — not supported here') });
+    if (!supported) opt.disabled = true;
+    select.append(opt);
+  }
+}
+
+function renderSigningKey() {
+  const info = $('sig-key-info');
+  info.replaceChildren();
+  const hasKey = Boolean(signingKey);
+  $('sig-export-key').disabled = !hasKey;
+  $('sig-delete-key').disabled = !hasKey;
+  $('sig-sign').disabled = !hasKey;
+  if (!hasKey) {
+    info.append(el('p', { class: 'sig-muted', text: 'No signing key yet. Generate one to start issuing signed documents.' }));
+    return;
+  }
+  const spec = ALGORITHMS[signingKey.alg];
+  info.append(
+    el('dl', { class: 'sig-dl' }, [
+      el('dt', { text: 'Algorithm' }),
+      el('dd', {}, [
+        signingKey.alg + ' ',
+        el('span', {
+          class: 'sig-badge ' + (spec.quantumResistant ? 'sig-badge-pq' : 'sig-badge-classic'),
+          text: spec.quantumResistant ? 'Quantum-resistant' : 'Classical',
+        }),
+      ]),
+      el('dt', { text: 'Key ID' }),
+      el('dd', { class: 'sig-mono', text: signingKey.kid }),
+      el('dt', { text: 'Created' }),
+      el('dd', { text: new Date(signingKey.createdAt).toLocaleString() }),
+    ]),
+  );
+}
+
+async function onGenerateKey() {
+  const status = $('sig-key-status');
+  const alg = $('sig-alg').value;
+  if (signingKey && !confirm('Replace the current signing key? Documents it signed will still verify if its public key stays in your keyring.')) {
+    return;
+  }
+  flash(status, `Generating ${alg} key…`);
+  try {
+    const key = await generateSigningKey(alg);
+    const createdAt = await saveSigningKey(key);
+    signingKey = { ...key, createdAt };
+    trustedKeys = addTrustedKey({
+      alg: key.alg,
+      kid: key.kid,
+      label: `${SHOP_NAME} (${key.alg})`,
+      publicKey: key.publicKey,
+    });
+    renderSigningKey();
+    renderKeyring();
+    $('sig-pubkey-out').value = '';
+    flash(status, 'New signing key created and added to your trusted keyring.');
+  } catch (err) {
+    flash(status, 'Key generation failed: ' + err.message, true);
+  }
+}
+
+async function onDeleteKey() {
+  if (!confirm('Delete the signing key from this browser? This cannot be undone. Its public key stays in your trusted keyring.')) return;
+  await deleteSigningKey();
+  signingKey = null;
+  renderSigningKey();
+  $('sig-pubkey-out').value = '';
+  flash($('sig-key-status'), 'Signing key deleted.');
+}
+
+function onExportKey() {
+  const out = $('sig-pubkey-out');
+  out.value = exportPublicKey(signingKey, `${SHOP_NAME} (${signingKey.alg})`);
+  out.hidden = false;
+  copyText(out.value, $('sig-key-status'));
+}
+
+// ---------- issue panel ----------
+
+function currentDocType() {
+  return document.querySelector('input[name="sig-doc-type"]:checked').value;
+}
+
+function renderDocTypeForms() {
+  const type = currentDocType();
+  $('sig-receipt-form').hidden = type !== 'receipt';
+  $('sig-voucher-form').hidden = type !== 'voucher';
+}
+
+function buildMenuInputs() {
+  const list = $('sig-menu-items');
+  MENU.forEach((item, i) => {
+    const input = el('input', { type: 'number', min: '0', max: '20', value: i === 0 ? '1' : '0', id: `sig-qty-${i}` });
+    input.addEventListener('input', updateReceiptTotal);
+    list.append(
+      el('label', { class: 'sig-menu-row', for: `sig-qty-${i}` }, [
+        el('span', { text: item.name }),
+        el('span', { class: 'sig-muted', text: money(item.unitCents) }),
+        input,
+      ]),
+    );
+  });
+  updateReceiptTotal();
+}
+
+function receiptItems() {
+  return MENU.map((item, i) => ({ ...item, qty: Math.max(0, Math.min(20, parseInt($(`sig-qty-${i}`).value, 10) || 0)) }))
+    .filter((item) => item.qty > 0);
+}
+
+function receiptTotals(items) {
+  const subtotalCents = items.reduce((n, i) => n + i.unitCents * i.qty, 0);
+  const taxCents = Math.round((subtotalCents * TAX_RATE_BPS) / 10000);
+  return { subtotalCents, taxCents, totalCents: subtotalCents + taxCents };
+}
+
+function updateReceiptTotal() {
+  const { subtotalCents, taxCents, totalCents } = receiptTotals(receiptItems());
+  $('sig-receipt-total').textContent =
+    `Subtotal ${money(subtotalCents)} · Tax ${money(taxCents)} · Total ${money(totalCents)}`;
+}
+
+function buildPayload(type) {
+  if (type === 'receipt') {
+    const items = receiptItems().map(({ name, qty, unitCents }) => ({ name, qty, unitCents }));
+    if (!items.length) throw new Error('Add at least one item to the order.');
+    return {
+      store: SHOP_NAME,
+      orderId: 'DG-' + randomCode(2),
+      customer: $('sig-customer').value.trim().slice(0, 80) || 'Guest',
+      items,
+      ...receiptTotals(items),
+      currency: 'USD',
+    };
+  }
+  const amountCents = Math.round(parseFloat($('sig-voucher-amount').value) * 100);
+  if (!Number.isSafeInteger(amountCents) || amountCents < 100 || amountCents > 50000) {
+    throw new Error('Voucher amount must be between $1 and $500.');
+  }
+  const validUntil = $('sig-voucher-expiry').value;
+  if (!/^\d{4}-\d{2}-\d{2}$/.test(validUntil)) throw new Error('Choose an expiry date.');
+  return {
+    store: SHOP_NAME,
+    code: randomCode(),
+    amountCents,
+    currency: 'USD',
+    recipient: $('sig-voucher-to').value.trim().slice(0, 80) || 'Bearer',
+    from: $('sig-voucher-from').value.trim().slice(0, 80),
+    message: $('sig-voucher-message').value.trim().slice(0, 200),
+    validUntil,
+  };
+}
+
+async function onSign(event) {
+  event.preventDefault();
+  const status = $('sig-issue-status');
+  const type = currentDocType();
+  try {
+    const payload = buildPayload(type);
+    flash(status, 'Signing…');
+    const token = await signDocument(signingKey, type, payload);
+    $('sig-token-out').value = token;
+    $('sig-token-actions').hidden = false;
+    const id = type === 'receipt' ? payload.orderId : payload.code;
+    flash(status, `Signed ${type} ${id} with ${signingKey.alg} (${token.length.toLocaleString()} characters).`);
+  } catch (err) {
+    flash(status, 'Signing failed: ' + err.message, true);
+  }
+}
+
+function onDownloadToken() {
+  const token = $('sig-token-out').value;
+  const env = parseToken(token);
+  const id = env.type === 'receipt' ? env.payload.orderId : env.payload.code;
+  download(`daily-grind-${env.type}-${String(id).replace(/[^A-Za-z0-9-]/g, '')}.dg1.txt`, token);
+}
+
+function onSendToVerifier() {
+  $('sig-verify-input').value = $('sig-token-out').value;
+  $('sig-verify-panel').scrollIntoView({ behavior: 'smooth' });
+  onVerify();
+}
+
+// ---------- verify panel ----------
+
+function renderDocument(env) {
+  const p = env.payload;
+  const rows = [];
+  const add = (label, value) => {
+    if (value === undefined || value === null || value === '') return;
+    rows.push(el('dt', { text: label }), el('dd', { text: String(value) }));
+  };
+  const asMoney = (v) => (Number.isSafeInteger(v) ? money(v) : String(v));
+  add('Type', env.type === 'receipt' ? 'Order receipt' : 'Gift voucher');
+  add('Issued', new Date(env.issuedAt).toLocaleString());
+  add('Algorithm', `${env.alg} — ${ALGORITHMS[env.alg].label}`);
+  add('Key ID', env.kid);
+  add('Store', p.store);
+  if (env.type === 'receipt') {
+    add('Order', p.orderId);
+    add('Customer', p.customer);
+    if (Array.isArray(p.items)) {
+      add('Items', p.items.map((i) => `${i.qty} × ${i.name} @ ${asMoney(i.unitCents)}`).join('\n'));
+    }
+    add('Subtotal', asMoney(p.subtotalCents));
+    add('Tax', asMoney(p.taxCents));
+    add('Total', asMoney(p.totalCents));
+  } else {
+    add('Voucher code', p.code);
+    add('Value', asMoney(p.amountCents));
+    add('For', p.recipient);
+    add('From', p.from);
+    add('Message', p.message);
+    add('Valid until', p.validUntil);
+  }
+  return el('dl', { class: 'sig-dl' }, rows);
+}
+
+async function onVerify() {
+  const out = $('sig-verify-result');
+  const token = $('sig-verify-input').value.trim();
+  out.replaceChildren();
+  out.className = 'sig-result';
+  if (!token) return;
+  out.append(el('p', { text: 'Verifying…' }));
+
+  const result = await verifyToken(token, trustedKeys);
+  const titles = {
+    trusted: '✔ Authentic — signature valid and signer trusted',
+    untrusted: '⚠ Valid signature from an unknown key',
+    invalid: '✖ Verification failed',
+  };
+  out.replaceChildren(el('h4', { text: titles[result.status] }), el('p', { text: result.reason }));
+  out.classList.add('sig-result-' + result.status);
+
+  if (result.status === 'trusted' && result.envelope.type === 'voucher') {
+    const today = new Date().toISOString().slice(0, 10);
+    if (String(result.envelope.payload.validUntil) < today) {
+      out.append(el('p', { class: 'sig-error', text: 'Note: this voucher has expired.' }));
+    }
+  }
+  if (result.status === 'untrusted') {
+    const btn = el('button', { type: 'button', class: 'btn sig-btn-small', text: 'Trust this signing key' });
+    btn.addEventListener('click', async () => {
+      const env = result.envelope;
+      if (!confirm(`Only trust key ${env.kid} if you obtained it from The Daily Grind through a channel you trust. Continue?`)) return;
+      trustedKeys = addTrustedKey({ alg: env.alg, kid: env.kid, label: `Trusted from document (${env.alg})`, publicKey: fromBase64Url(env.pub) });
+      renderKeyring();
+      onVerify();
+    });
+    out.append(btn);
+  }
+  if (result.envelope) {
+    out.append(
+      el('p', {
+        class: 'sig-muted',
+        text: result.status === 'trusted' ? 'Verified contents:' : 'Claimed contents (NOT verified — do not rely on these):',
+      }),
+      renderDocument(result.envelope),
+    );
+  }
+}
+
+// Demo helper: flips one cent on the total/value to show tamper detection.
+function onTamper() {
+  const input = $('sig-verify-input');
+  try {
+    const raw = input.value.trim().replace(/\s+/g, '');
+    const env = JSON.parse(new TextDecoder().decode(fromBase64Url(raw.slice(4))));
+    if (env.type === 'receipt') env.payload.totalCents -= 1;
+    else env.payload.amountCents += 100;
+    input.value = 'DG1.' + toBase64Url(new TextEncoder().encode(JSON.stringify(env)));
+    onVerify();
+  } catch {
+    flash($('sig-verify-result'), 'Paste a signed document into the verifier first.', true);
+  }
+}
+
+async function onVerifyFile(event) {
+  const file = event.target.files[0];
+  if (!file) return;
+  if (file.size > 64 * 1024) {
+    flash($('sig-verify-result'), 'File is too large to be a signed document.', true);
+    return;
+  }
+  $('sig-verify-input').value = (await file.text()).trim();
+  event.target.value = '';
+  onVerify();
+}
+
+// ---------- trusted keyring ----------
+
+function renderKeyring() {
+  const list = $('sig-keyring');
+  list.replaceChildren();
+  if (!trustedKeys.length) {
+    list.append(el('li', { class: 'sig-muted', text: 'No trusted keys yet.' }));
+    return;
+  }
+  for (const k of trustedKeys) {
+    const remove = el('button', { type: 'button', class: 'sig-link-btn', text: 'Remove' });
+    remove.addEventListener('click', () => {
+      if (!confirm(`Stop trusting "${k.label}"? Documents signed by it will no longer verify as authentic.`)) return;
+      trustedKeys = removeTrustedKey(k.kid);
+      renderKeyring();
+    });
+    const isOwn = signingKey && signingKey.kid === k.kid;
+    list.append(
+      el('li', {}, [
+        el('div', {}, [
+          el('strong', { text: k.label }),
+          isOwn ? el('span', { class: 'sig-badge sig-badge-classic', text: 'This browser' }) : '',
+        ]),
+        el('div', { class: 'sig-mono sig-muted', text: `${k.alg} · ${k.kid}` }),
+        remove,
+      ]),
+    );
+  }
+}
+
+async function onImportKey() {
+  const status = $('sig-keyring-status');
+  try {
+    const key = await importPublicKey($('sig-import-key').value);
+    trustedKeys = addTrustedKey(key);
+    $('sig-import-key').value = '';
+    renderKeyring();
+    flash(status, `Now trusting "${key.label}" (${key.alg}).`);
+  } catch (err) {
+    flash(status, err.message, true);
+  }
+}
+
+// ---------- init ----------
+
+async function init() {
+  if (!window.isSecureContext || !crypto.subtle) {
+    $('sig-unsupported').hidden = false;
+    $('sig-app').hidden = true;
+    return;
+  }
+  await initAlgorithmSelect();
+  buildMenuInputs();
+
+  const expiry = new Date();
+  expiry.setFullYear(expiry.getFullYear() + 1);
+  $('sig-voucher-expiry').value = expiry.toISOString().slice(0, 10);
+
+  trustedKeys = loadTrustedKeys();
+  try {
+    signingKey = await loadSigningKey();
+    if (signingKey) $('sig-alg').value = signingKey.alg;
+  } catch (err) {
+    flash($('sig-key-status'), 'Could not load the saved signing key: ' + err.message, true);
+  }
+  renderSigningKey();
+  renderKeyring();
+  renderDocTypeForms();
+
+  $('sig-generate-key').addEventListener('click', onGenerateKey);
+  $('sig-delete-key').addEventListener('click', onDeleteKey);
+  $('sig-export-key').addEventListener('click', onExportKey);
+  document.querySelectorAll('input[name="sig-doc-type"]').forEach((r) => r.addEventListener('change', renderDocTypeForms));
+  $('sig-issue-form').addEventListener('submit', onSign);
+  $('sig-copy-token').addEventListener('click', () => copyText($('sig-token-out').value, $('sig-issue-status')));
+  $('sig-download-token').addEventListener('click', onDownloadToken);
+  $('sig-send-verify').addEventListener('click', onSendToVerifier);
+  $('sig-verify').addEventListener('click', onVerify);
+  $('sig-tamper').addEventListener('click', onTamper);
+  $('sig-verify-file').addEventListener('change', onVerifyFile);
+  $('sig-import-btn').addEventListener('click', onImportKey);
+}
+
+init();
