+      case 'ArrowUp':
+        next = current + 1;
+        break;
+      case 'ArrowDown':
+        next = current - 1;
+        break;
+      case 'ArrowRight':
+        next = rtl ? current - 1 : current + 1;
+        break;
+      case 'ArrowLeft':
+        next = rtl ? current + 1 : current - 1;
+        break;
+      case 'Home':
+        next = 1;
+        break;
+      case 'End':
+        next = this.max;
+        break;
+      case ' ':
