--- /dev/null
+++ b/src/utils/dialog.ts
@@ -0,0 +1,38 @@
+/**
+ * Opens a `<dialog closedby="any">` as a modal and, where `closedby` isn't
+ * supported (Safari), adds the click-outside-to-close behavior by hand.
+ * Returns a cleanup function that removes the fallback listeners.
+ */
+export function showModalWithLightDismiss(dialog: HTMLDialogElement): () => void {
+  if (!dialog.open) dialog.showModal();
+
+  if ('closedBy' in HTMLDialogElement.prototype) return () => {};
+
+  // Test the pointer position, not event.target: the dialog is also the target
+  // for clicks on its own padding and the gaps between its children
+  const isOutside = (event: PointerEvent) => {
+    const rect = dialog.getBoundingClientRect();
+    return (
+      event.clientX < rect.left ||
+      event.clientX > rect.right ||
+      event.clientY < rect.top ||
+      event.clientY > rect.bottom
+    );
+  };
+
+  let pressedOutside = false;
+  const onPointerDown = (event: PointerEvent) => {
+    pressedOutside = isOutside(event);
+  };
+  // Require both press and release outside so a text-selection drag doesn't dismiss
+  const onPointerUp = (event: PointerEvent) => {
+    if (pressedOutside && isOutside(event)) dialog.close();
+  };
+
+  dialog.addEventListener('pointerdown', onPointerDown);
+  dialog.addEventListener('pointerup', onPointerUp);
+  return () => {
+    dialog.removeEventListener('pointerdown', onPointerDown);
+    dialog.removeEventListener('pointerup', onPointerUp);
+  };
+}

