+- Maple Oat Latte: espresso with creamy oat milk and a hint of real Vermont maple syrup. Dairy-free by default. Served hot or iced.
+- Cold Brew: coffee steeped for 18 hours for maximum smoothness, low acidity, naturally sweet, higher caffeine than drip. Served over ice; can add oat milk or maple syrup.
+If asked about anything else, politely steer the guest back to these two drinks. Keep answers short (2-4 sentences).`;
+
+      const $ = (id) => document.getElementById(id);
+
+      // Every live session is tracked here so it can be destroyed on page exit.
+      const liveSessions = new Set();
+
+      function track(session) {
+        liveSessions.add(session);
+        return session;
+      }
+
+      function destroySession(session) {
+        if (!session) return;
+        liveSessions.delete(session);
+        try { session.destroy(); } catch { /* already destroyed */ }
+      }
+
+      // Spec renamed inputUsage/inputQuota -> contextUsage/contextWindow; support both.
+      function usageOf(session) {
+        const used = session.contextUsage ?? session.inputUsage ?? 0;
+        const total = session.contextWindow ?? session.inputQuota ?? 0;
+        return { used, total };
+      }
+
+      async function checkAvailability(statusEl) {
+        if (!('LanguageModel' in self)) {
+          statusEl.textContent = 'Built-in AI is not supported in this browser. Try a recent version of Chrome on desktop.';
+          return 'unavailable';
+        }
+        const availability = await LanguageModel.availability(LANG_OPTIONS);
+        if (availability === 'unavailable') {
+          statusEl.textContent = 'The on-device model is unavailable on this device.';
+        }
+        return availability;
+      }
+
+      // Creates a session, surfacing model download progress if a download is needed.
+      // Must be called from a user gesture when the model is "downloadable".
+      async function createSession({ statusEl, progressEl, signal, initialPrompts }) {
+        const availability = await checkAvailability(statusEl);
+        if (availability === 'unavailable') return null;
+
+        if (availability !== 'available') {
+          statusEl.textContent = 'Downloading the on-device model…';
+          progressEl.hidden = false;
+          progressEl.removeAttribute('value'); // indeterminate until first event
+        }
+
+        try {
+          const session = await LanguageModel.create({
+            ...LANG_OPTIONS,
+            initialPrompts,
+            signal,
+            monitor(m) {
+              m.addEventListener('downloadprogress', (e) => {
+                progressEl.hidden = false;
+                progressEl.value = e.loaded;
+                statusEl.textContent = e.loaded >= 1
+                  ? 'Download complete, preparing model…'
+                  : `Downloading the on-device model… ${Math.round(e.loaded * 100)}%`;
+              });
+            },
+          });
+          return track(session);
+        } finally {
+          progressEl.hidden = true;
+        }
+      }
+
+      function describeError(err) {
+        if (err?.name === 'AbortError') return 'Request cancelled.';
+        if (err?.name === 'NotAllowedError') return 'Please click the button again to allow the model to start.';
+        if (err?.name === 'QuotaExceededError') return 'That input is too long for the on-device model.';
+        if (err?.name === 'NotSupportedError') return 'This request is not supported by the on-device model.';
+        return `Something went wrong: ${err?.message ?? err}`;
+      }
+
+      // ---- 1. Ask the Barista (streaming) ----
+
+      const barista = {
+        btn: $('ask-the-barista'),
+        stopBtn: $('barista-stop'),
+        input: $('barista-question'),
+        output: $('barista-answer'),
+        status: $('barista-status'),
+        progress: $('barista-progress'),
+        // A pristine session holding only the system prompt; each question runs in a clone
+        // so answers stay independent and context never grows unbounded.
+        baseSession: null,
+        controller: null,
+      };
+
+      barista.btn.addEventListener('click', async () => {
+        const question = barista.input.value.trim();
+        if (!question) {
+          barista.status.textContent = 'Please type a question first.';
+          return;
+        }
+
+        barista.controller?.abort();
+        const controller = new AbortController();
+        barista.controller = controller;
+        const { signal } = controller;
+
+        barista.btn.disabled = true;
+        barista.stopBtn.hidden = false;
+        barista.output.textContent = '';
+        let turn = null;
+
+        try {
+          if (!barista.baseSession) {
+            barista.status.textContent = 'Checking on-device model availability…';
+            barista.baseSession = await createSession({
+              statusEl: barista.status,
+              progressEl: barista.progress,
+              signal,
+              initialPrompts: [{ role: 'system', content: MENU_CONTEXT }],
+            });
+            if (!barista.baseSession) return;
+          }
+
+          turn = track(await barista.baseSession.clone({ signal }));
+          barista.status.textContent = 'The barista is thinking…';
+
+          const stream = turn.promptStreaming(question, { signal });
+          for await (const chunk of stream) {
+            barista.output.append(chunk);
+          }
+          barista.status.textContent = '';
+        } catch (err) {
+          barista.status.textContent = describeError(err);
+        } finally {
+          destroySession(turn);
+          if (barista.controller === controller) {
+            barista.controller = null;
+            barista.btn.disabled = false;
+            barista.stopBtn.hidden = true;
+          }
+        }
+      });
+
+      barista.stopBtn.addEventListener('click', () => barista.controller?.abort());
+
+      // ---- 2. Customer Feedback Analyzer (structured JSON output) ----
+
+      const SENTIMENT_SCHEMA = {
+        type: 'object',
+        properties: {
+          score: { type: 'number', minimum: -1, maximum: 1 },
+          category: { type: 'string', enum: ['positive', 'neutral', 'negative', 'mixed'] },
+        },
+        required: ['score', 'category'],
+        additionalProperties: false,
+      };
+
+      const sentiment = {
+        btn: $('sentiment-btn'),
+        input: $('feedback-input'),
+        output: $('sentiment-result'),
+        status: $('sentiment-status'),
+        progress: $('sentiment-progress'),
+        baseSession: null,
+        controller: null,
+      };
+
+      sentiment.btn.addEventListener('click', async () => {
+        const feedback = sentiment.input.value.trim();
+        if (!feedback) {
+          sentiment.status.textContent = 'Please paste some customer feedback first.';
+          return;
+        }
+
+        sentiment.controller?.abort();
+        const controller = new AbortController();
+        sentiment.controller = controller;
+        const { signal } = controller;
+
+        sentiment.btn.disabled = true;
+        sentiment.output.textContent = '';
+        let turn = null;
+
+        try {
+          if (!sentiment.baseSession) {
+            sentiment.status.textContent = 'Checking on-device model availability…';
+            sentiment.baseSession = await createSession({
+              statusEl: sentiment.status,
+              progressEl: sentiment.progress,
+              signal,
+              initialPrompts: [{
+                role: 'system',
+                content: 'You analyze coffee shop customer feedback. Return a sentiment score from -1 (very negative) to 1 (very positive) and a category.',
+              }],
+            });
+            if (!sentiment.baseSession) return;
+          }
+
+          // Fresh clone per review so earlier reviews don't bias the next one.
+          turn = track(await sentiment.baseSession.clone({ signal }));
+          sentiment.status.textContent = 'Analyzing feedback…';
+
+          const raw = await turn.prompt(`Customer feedback:\n"""${feedback}"""`, {
+            signal,
+            responseConstraint: SENTIMENT_SCHEMA,
+          });
+          const result = JSON.parse(raw);
+          sentiment.output.textContent = JSON.stringify(result, null, 2);
+          sentiment.status.textContent = '';
+        } catch (err) {
+          sentiment.status.textContent = err instanceof SyntaxError
+            ? 'The model returned an unexpected format. Please try again.'
+            : describeError(err);
+        } finally {
+          destroySession(turn);
+          if (sentiment.controller === controller) {
+            sentiment.controller = null;
+            sentiment.btn.disabled = false;
+          }
+        }
+      });
+
+      // ---- 3. Conversation Branching (clone + context tracking + cleanup) ----
+
+      const MAX_BRANCHES = 4;
+
+      const branching = {
+        sendBtn: $('branch-send'),
+        cloneBtn: $('clone-btn'),
+        input: $('branch-input'),
+        output: $('branch-output'),
+        status: $('branch-status'),
+        progress: $('branch-progress'),
+        list: $('branch-list'),
+        branches: [], // { id, name, session, lastUsed, transcript }
+        activeId: null,
+        nextId: 1,
+        controller: null,
+      };
+
+      const activeBranch = () => branching.branches.find((b) => b.id === branching.activeId) ?? null;
+
+      function addBranch(session, name, transcript = '') {
+        const branch = { id: branching.nextId++, name, session, lastUsed: Date.now(), transcript };
+        session.addEventListener?.('contextoverflow', () => onOverflow(branch));
+        session.addEventListener?.('quotaoverflow', () => onOverflow(branch));
+        branching.branches.push(branch);
+        branching.activeId = branch.id;
+        pruneBranches();
+        return branch;
+      }
+
+      function onOverflow(branch) {
+        branching.status.textContent = `"${branch.name}" ran out of context; the oldest messages were dropped.`;
+      }
+
+      function removeBranch(id) {
+        const idx = branching.branches.findIndex((b) => b.id === id);
+        if (idx === -1) return;
+        const [branch] = branching.branches.splice(idx, 1);
+        destroySession(branch.session);
+        if (branching.activeId === id) {
+          const fallback = branching.branches.at(-1);
+          branching.activeId = fallback?.id ?? null;
+        }
+      }
