+      // Keep at most MAX_BRANCHES sessions alive, evicting the least recently used
+      // non-active branch first to free memory on the device.
+      function pruneBranches() {
+        while (branching.branches.length > MAX_BRANCHES) {
+          const victim = branching.branches
+            .filter((b) => b.id !== branching.activeId)
+            .sort((a, b) => a.lastUsed - b.lastUsed)[0];
+          if (!victim) break;
+          removeBranch(victim.id);
+          branching.status.textContent = `Cleaned up unused branch "${victim.name}" to free resources.`;
+        }
+      }
+
+      function renderBranches() {
+        branching.list.replaceChildren(...branching.branches.map((branch) => {
+          const { used, total } = usageOf(branch.session);
+          const li = document.createElement('li');
+          li.classList.toggle('active', branch.id === branching.activeId);
+
+          const label = document.createElement('span');
+          label.textContent = `${branch.name}${branch.id === branching.activeId ? ' (active)' : ''}`;
+
+          const meter = document.createElement('meter');
+          meter.min = 0;
+          meter.max = total || 1;
+          meter.value = used;
+          meter.high = (total || 1) * 0.8;
+          meter.title = `${used} / ${total} tokens`;
+
+          const usage = document.createElement('small');
+          usage.textContent = total ? `${used} / ${total} tokens` : `${used} tokens`;
+
+          const switchBtn = document.createElement('button');
+          switchBtn.type = 'button';
+          switchBtn.className = 'btn secondary';
+          switchBtn.textContent = 'Switch';
+          switchBtn.disabled = branch.id === branching.activeId;
+          switchBtn.addEventListener('click', () => {
+            branching.activeId = branch.id;
+            branch.lastUsed = Date.now();
+            branching.output.textContent = branch.transcript;
+            renderBranches();
+          });
+
+          const closeBtn = document.createElement('button');
+          closeBtn.type = 'button';
+          closeBtn.className = 'btn secondary';
+          closeBtn.textContent = 'Close';
+          closeBtn.addEventListener('click', () => {
+            branching.controller?.abort();
+            removeBranch(branch.id);
+            branching.output.textContent = activeBranch()?.transcript ?? '';
+            renderBranches();
+          });
+
+          li.append(label, usage, meter, switchBtn, closeBtn);
+          return li;
+        }));
+      }
+
+      function setBranchBusy(busy) {
+        branching.sendBtn.disabled = busy;
+        branching.cloneBtn.disabled = busy;
+      }
+
+      async function ensureRootBranch(signal) {
+        if (activeBranch()) return activeBranch();
+        branching.status.textContent = 'Checking on-device model availability…';
+        const session = await createSession({
+          statusEl: branching.status,
+          progressEl: branching.progress,
+          signal,
+          initialPrompts: [{ role: 'system', content: MENU_CONTEXT }],
+        });
