+        const branch = addBranch(session, 'Main');
+        renderBranches();
+        return branch;
+      }
+
+      branching.sendBtn.addEventListener('click', async () => {
+        const message = branching.input.value.trim();
+        if (!message) {
+          branching.status.textContent = 'Please type a message first.';
+          return;
+        }
+
+        const controller = new AbortController();
+        branching.controller = controller;
+        const { signal } = controller;
+        setBranchBusy(true);
+
+        try {
+          const branch = await ensureRootBranch(signal);
+          if (!branch) return;
