+          for await (const chunk of branch.session.promptStreaming(message, { signal })) {
+            branch.transcript += chunk;
+            if (branching.activeId === branch.id) branching.output.textContent = branch.transcript;
+          }
+          if (branching.status.textContent === 'Thinking…') branching.status.textContent = '';
+        } catch (err) {
+          branching.status.textContent = describeError(err);
+        } finally {
+          if (branching.controller === controller) branching.controller = null;
+          setBranchBusy(false);
+          renderBranches();
+        }
+      });
+
+      $('clone-btn').addEventListener('click', async () => {
+        const controller = new AbortController();
+        branching.controller = controller;
+        const { signal } = controller;
+        setBranchBusy(true);
+
