+          }
+        } catch (err) {
+          branching.status.textContent = describeError(err);
+        } finally {
+          if (branching.controller === controller) branching.controller = null;
+          setBranchBusy(false);
+          renderBranches();
+        }
+      });
+
+      // ---- Resource cleanup ----
+
+      // Release on-device model memory when the page goes away.
+      window.addEventListener('pagehide', () => {
+        barista.controller?.abort();
+        sentiment.controller?.abort();
+        branching.controller?.abort();
+        for (const session of [...liveSessions]) destroySession(session);
