+          const msg = {
+            unavailable: 'The on-device model is unavailable on this device.',
+            downloadable: 'The on-device model will download the first time you ask a question.',
+            downloading: 'The on-device model is downloading in the background…',
+            available: '',
+          }[availability] ?? '';
