+        }).catch(() => { /* surfaced again on click */ });
+      } else {
+        for (const el of [barista.status, sentiment.status, branching.status]) {
+          el.textContent = 'Built-in AI is not supported in this browser. Try a recent version of Chrome on desktop.';
+        }
+      }
+    })();
+  </script>
+
