+      } catch (e) {
+        console.error(e);
+        setStatus('passkey-status', "We couldn't create a passkey. Please try again.", true);
+      } finally {
+        createButton.disabled = false;
+      }
+    });
+
+    // ---- Init ----
+
+    async function init() {
+      try {
+        currentUser = await api('/api/user');
+      } catch (e) {
+        console.error(e);
+        setStatus('profile-status', "We couldn't load your account. Please refresh the page.", true);
+        return;
+      }
+      $('profile-email').textContent = currentUser.name;
+      $('display-name').value = currentUser.displayName ?? '';
+      $('greeting').textContent = `Welcome back, ${currentUser.displayName || currentUser.name}.`;
