+      setUpCreateButton();
+
+      try {
+        await loadPasskeys();
+      } catch (e) {
+        console.error(e);
+        list.setAttribute('aria-busy', 'false');
+        setStatus('passkey-status', "We couldn't load your passkeys. Please refresh the page.", true);
