+++ b/public/assets/account.js
@@ -0,0 +1,607 @@
+// My Account: passkey sign-up, sign-in, passkey management, profile updates, and reauthentication.
+(() => {
+  const {
+    browserSupportsWebAuthn,
+    browserSupportsWebAuthnAutofill,
+    sendSignal,
+    startAuthentication,
+    startRegistration,
+  } = window.SimpleWebAuthnBrowser;
+
+  const $ = (selector, root = document) => root.querySelector(selector);
+
+  const els = {
+    notice: $('#notice'),
+    loading: $('#loading'),
+    unsupported: $('#unsupported'),
+    signedOut: $('#signed-out'),
+    signedIn: $('#signed-in'),
+    signinForm: $('#signin-form'),
+    signinEmail: $('#signin-email'),
+    registerForm: $('#register-form'),
+    profileForm: $('#profile-form'),
+    welcomeName: $('#welcome-name'),
+    memberSince: $('#member-since'),
+    passkeyList: $('#passkey-list'),
+    passkeyTemplate: $('#passkey-item-template'),
+    addPasskey: $('#add-passkey'),
+    signout: $('#signout'),
+    reauthDialog: $('#reauth-dialog'),
+    reauthReason: $('#reauth-reason'),
+    reauthError: $('#reauth-error'),
+    reauthConfirm: $('#reauth-confirm'),
+    reauthContinue: $('#reauth-continue'),
+    confirmDialog: $('#confirm-dialog'),
+    confirmMessage: $('#confirm-message'),
+  };
+
+  const state = {
+    rpID: null,
+    user: null,
+    highlightPasskeyId: null,
+  };
+
+  /* --------------------------------------------------------------------------------------------
+   * Helpers
+   * ------------------------------------------------------------------------------------------ */
+
+  class ApiError extends Error {
+    constructor(status, data) {
+      super(data?.message || 'Something went wrong. Please try again.');
+      this.status = status;
+      this.code = data?.error || 'unknown';
+      this.data = data || {};
+    }
+  }
+
+  async function api(method, path, body) {
+    const init = { method, headers: { Accept: 'application/json' } };
+    if (body !== undefined) {
+      init.headers['Content-Type'] = 'application/json';
+      init.body = JSON.stringify(body);
+    }
+    const res = await fetch(path, init);
+    const data = await res.json().catch(() => null);
+    if (!res.ok) throw new ApiError(res.status, data);
+    return data;
+  }
+
+  function showNotice(message, { error = false } = {}) {
+    els.notice.textContent = message;
+    els.notice.classList.toggle('notice-error', error);
+    els.notice.hidden = false;
+  }
+
+  function clearNotice() {
+    els.notice.hidden = true;
+    els.notice.textContent = '';
+  }
+
+  function isAbort(err) {
+    return err?.code === 'ERROR_CEREMONY_ABORTED' || err?.name === 'AbortError';
+  }
+
+  /** Turns WebAuthn and API errors into a message for the customer, or null to stay quiet. */
+  function describeError(err) {
+    if (isAbort(err)) return null;
+    if (err instanceof ApiError) return err.message;
+    if (err?.code === 'ERROR_AUTHENTICATOR_PREVIOUSLY_REGISTERED' || err?.name === 'InvalidStateError') {
+      return 'This device or password manager already has a passkey for your account.';
+    }
+    if (err?.name === 'NotAllowedError') {
+      return 'The passkey request was cancelled or timed out.';
+    }
+    if (err?.name === 'SecurityError') {
+      return 'Passkeys aren’t available on this address. Please make sure you’re on the official Daily Grind site.';
+    }
+    console.error(err);
+    return err?.message || 'Something went wrong. Please try again.';
+  }
+
+  function reportError(err) {
+    const message = describeError(err);
+    if (message) showNotice(message, { error: true });
+  }
+
+  /** Disables a button while an async action runs, ignoring repeat clicks. */
+  async function busy(button, action) {
+    if (button.disabled) return;
+    button.disabled = true;
+    try {
+      return await action();
+    } finally {
+      button.disabled = false;
+    }
+  }
+
+  const dateFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' });
+  const formatDate = (iso) => dateFormat.format(new Date(iso));
+
+  /* --------------------------------------------------------------------------------------------
+   * Signals: help the customer's passkey provider keep its list in sync with our records.
+   * These are best-effort and silently skipped on browsers that don't support them.
+   * ------------------------------------------------------------------------------------------ */
+
+  function signal(opts) {
+    sendSignal({ rpID: state.rpID, ...opts }).catch(() => {});
+  }
+
+  function signalAccountState() {
+    const { user } = state;
+    if (!user) return;
+    signal({
+      signalName: 'allAcceptedCredentials',
+      userID: user.webauthnUserID,
+      allAcceptedCredentialIDs: user.passkeys.map((p) => p.id),
+    });
+    signal({
+      signalName: 'currentUserDetails',
+      userID: user.webauthnUserID,
+      name: user.email,
+      displayName: user.name,
+    });
+  }
+
+  /* --------------------------------------------------------------------------------------------
+   * Rendering
+   * ------------------------------------------------------------------------------------------ */
+
+  function render() {
+    const { user } = state;
+    els.loading.hidden = true;
+    els.signedOut.hidden = Boolean(user);
+    els.signedIn.hidden = !user;
+    window.DailyGrindNav?.setSignedIn(Boolean(user));
+    if (!user) return;
+
+    els.welcomeName.textContent = user.name;
+    els.memberSince.textContent = `Member since ${formatDate(user.createdAt)}`;
+    if (document.activeElement?.form !== els.profileForm) {
+      els.profileForm.elements.name.value = user.name;
+      els.profileForm.elements.email.value = user.email;
+    }
+    renderPasskeys();
+  }
+
+  function renderPasskeys() {
+    const { passkeys } = state.user;
+    els.passkeyList.replaceChildren(...passkeys.map(renderPasskey));
+  }
+
+  function renderPasskey(passkey) {
+    const item = els.passkeyTemplate.content.firstElementChild.cloneNode(true);
+    item.dataset.id = passkey.id;
+
+    const nameEl = $('.passkey-name', item);
+    nameEl.textContent = passkey.name;
+    if (passkey.id === state.highlightPasskeyId) {
+      const badge = document.createElement('span');
+      badge.className = 'badge badge-new';
+      badge.textContent = 'New';
+      nameEl.append(badge);
+    }
+
+    const meta = [
+      passkey.synced ? 'Synced across your devices' : 'Saved on one device',
+      `Created ${formatDate(passkey.createdAt)}`,
+    ];
+    if (passkey.lastUsedAt) meta.push(`Last used ${formatDate(passkey.lastUsedAt)}`);
+    $('.passkey-meta', item).textContent = meta.join(' · ');
+
+    const renameInput = $('.rename-form input', item);
+    const inputId = `rename-${passkey.id}`;
+    renameInput.id = inputId;
+    $('.rename-form label', item).htmlFor = inputId;
+
+    $('[data-action="rename"]', item).setAttribute('aria-label', `Rename ${passkey.name}`);
+    $('[data-action="remove"]', item).setAttribute('aria-label', `Remove ${passkey.name}`);
+    return item;
+  }
+
+  function setUser(user) {
+    state.user = user;
+    render();
+  }
+
+  /* --------------------------------------------------------------------------------------------
+   * Sign in
+   * ------------------------------------------------------------------------------------------ */
+
+  let autofillActive = false;
+
+  async function completeSignIn(response) {
+    try {
+      const { user } = await api('POST', '/api/login/verify', { response });
+      clearNotice();
+      setUser(user);
+      showNotice(`Signed in. Welcome back, ${user.name}!`);
+      signalAccountState();
+    } catch (err) {
+      if (err instanceof ApiError && err.code === 'unknown_credential' && err.data.credentialID) {
+        // The passkey was deleted from the account; ask the provider to stop offering it.
+        signal({ signalName: 'unknownCredential', credentialID: err.data.credentialID });
+      }
+      throw err;
+    }
+  }
+
+  /**
+   * Passkey autofill: offers saved passkeys in the email field's autofill menu. The request stays
+   * pending in the background until the customer picks a passkey or another ceremony aborts it.
+   */
+  async function startAutofillSignIn() {
+    if (state.user || autofillActive || !(await browserSupportsWebAuthnAutofill())) return;
+    autofillActive = true;
+    try {
+      const { options } = await api('POST', '/api/login/options', {});
+      const response = await startAuthentication({ optionsJSON: options, useBrowserAutofill: true });
+      autofillActive = false;
+      await completeSignIn(response);
+    } catch (err) {
+      autofillActive = false;
+      if (isAbort(err)) return;
+      reportError(err);
+      // If the server rejected the passkey (e.g. it was removed or the request expired), keep
+      // autofill available for another attempt.
+      const retryable = ['unknown_credential', 'challenge_expired', 'verification_failed'];
+      if (err instanceof ApiError && retryable.includes(err.code) && !state.user) startAutofillSignIn();
+    }
+  }
+
+  async function signInWithPasskey() {
+    clearNotice();
+    try {
+      // Starting a new ceremony aborts any pending autofill request.
+      const { options } = await api('POST', '/api/login/options', {});
+      const response = await startAuthentication({ optionsJSON: options });
+      await completeSignIn(response);
+    } catch (err) {
+      reportError(err);
+    } finally {
+      if (!state.user) startAutofillSignIn();
+    }
+  }
+
+  els.signinForm.addEventListener('submit', (event) => {
+    event.preventDefault();
+    busy(event.submitter || $('button', els.signinForm), signInWithPasskey);
+  });
+
+  /* --------------------------------------------------------------------------------------------
+   * Create an account
+   * ------------------------------------------------------------------------------------------ */
+
+  async function register(form) {
+    clearNotice();
+    const name = form.elements.name.value.trim();
+    const email = form.elements.email.value.trim();
+    if (!name) {
+      form.elements.name.focus();
+      return showNotice('Please enter your name.', { error: true });
+    }
+    if (!form.elements.email.checkValidity() || !email) {
+      form.elements.email.focus();
+      return showNotice('Please enter a valid email address.', { error: true });
+    }
+
+    try {
+      const { options } = await api('POST', '/api/register/options', { name, email });
+      const response = await startRegistration({ optionsJSON: options });
+      const { user } = await api('POST', '/api/register/verify', { response });
+      form.reset();
+      state.highlightPasskeyId = user.passkeys[0]?.id;
+      setUser(user);
+      showNotice(`Welcome to The Daily Grind, ${user.name}! Your account is protected by a passkey.`);
+      signalAccountState();
+    } catch (err) {
+      reportError(err);
+      if (!state.user) startAutofillSignIn();
+    }
+  }
+
+  els.registerForm.addEventListener('submit', (event) => {
+    event.preventDefault();
+    busy(event.submitter || $('button', els.registerForm), () => register(els.registerForm));
+  });
+
+  /* --------------------------------------------------------------------------------------------
+   * Reauthentication
+   * ------------------------------------------------------------------------------------------ */
+
+  let pendingReauth = null;
+
+  /**
+   * Asks the customer to verify with one of their passkeys. Resolves once the server has recorded
+   * a fresh verification; rejects with an AbortError if the customer cancels.
+   *
+   * If `continueLabel` is given, the dialog shows a second button after verifying and resolves
+   * when it's clicked. Use this when the follow-up action starts another WebAuthn ceremony, since
+   * browsers require a fresh user gesture for each one.
+   */
+  function reauthenticate(reason, continueLabel) {
+    els.reauthReason.textContent = reason;
+    els.reauthError.hidden = true;
+    els.reauthConfirm.hidden = false;
+    els.reauthContinue.hidden = true;
+    els.reauthDialog.showModal();
+    return new Promise((resolve, reject) => {
+      pendingReauth = { resolve, reject, continueLabel };
+    });
+  }
+
+  function finishReauth() {
+    const pending = pendingReauth;
+    pendingReauth = null;
+    els.reauthDialog.close('verified');
+    pending?.resolve();
+  }
+
+  els.reauthConfirm.addEventListener('click', () => busy(els.reauthConfirm, async () => {
+    els.reauthError.hidden = true;
+    try {
+      const { options } = await api('POST', '/api/reauth/options', {});
+      const response = await startAuthentication({ optionsJSON: options });
+      const { user } = await api('POST', '/api/reauth/verify', { response });
+      state.user = user;
+      if (pendingReauth?.continueLabel) {
+        els.reauthReason.textContent = 'Thanks, you’re verified.';
+        els.reauthContinue.textContent = pendingReauth.continueLabel;
+        els.reauthConfirm.hidden = true;
+        els.reauthContinue.hidden = false;
+        els.reauthContinue.focus();
+      } else {
+        finishReauth();
+      }
+    } catch (err) {
+      if (err instanceof ApiError && err.code === 'unauthenticated') {
+        els.reauthDialog.close('cancel');
+        return handleSignedOut();
+      }
+      const message = describeError(err);
+      if (message) {
+        els.reauthError.textContent = message;
+        els.reauthError.hidden = false;
+      }
+    }
+  }));
+
+  els.reauthContinue.addEventListener('click', finishReauth);
+
+  els.reauthDialog.addEventListener('close', () => {
+    if (pendingReauth) {
+      pendingReauth.reject(Object.assign(new Error('Verification cancelled.'), { name: 'AbortError' }));
+      pendingReauth = null;
+    }
+  });
+
+  /**
+   * Runs an action that may require a recent passkey verification. If the server says the last
+   * verification is too old, asks the customer to confirm it's them and then retries once.
+   */
+  async function withReauth(action, reason, continueLabel) {
+    try {
+      return await action();
+    } catch (err) {
+      if (!(err instanceof ApiError) || err.code !== 'reauth_required') throw err;
+      await reauthenticate(reason, continueLabel);
