+    reportError(err);
+  }
+
+  /* --------------------------------------------------------------------------------------------
+   * Profile
+   * ------------------------------------------------------------------------------------------ */
+
+  async function saveProfile(form) {
+    clearNotice();
+    const name = form.elements.name.value.trim();
+    const email = form.elements.email.value.trim();
+    if (!name) {
+      form.elements.name.focus();
+      return showNotice('Please enter your name.', { error: true });
+    }
+    if (!form.elements.email.checkValidity() || !email) {
+      form.elements.email.focus();
+      return showNotice('Please enter a valid email address.', { error: true });
+    }
+
+    try {
+      const { user } = await withReauth(
+        () => api('PATCH', '/api/profile', { name, email }),
+        'To change the email on your account, please verify with one of your passkeys.',
+      );
+      setUser(user);
+      els.profileForm.elements.name.value = user.name;
+      els.profileForm.elements.email.value = user.email;
+      showNotice('Your profile has been updated.');
+      // Lets passkey providers show the updated name and email in their account pickers.
+      signalAccountState();
+    } catch (err) {
+      reportAccountError(err);
+    }
+  }
+
+  els.profileForm.addEventListener('submit', (event) => {
+    event.preventDefault();
+    busy(event.submitter || $('button', els.profileForm), () => saveProfile(els.profileForm));
+  });
+
+  /* --------------------------------------------------------------------------------------------
+   * Passkey management
+   * ------------------------------------------------------------------------------------------ */
+
+  async function addPasskey() {
+    clearNotice();
+    try {
+      const { options } = await withReauth(
+        () => api('POST', '/api/passkeys/options', {}),
+        'Before creating a new passkey, please verify with one you already have.',
+        'Continue to create passkey',
+      );
+      const response = await startRegistration({ optionsJSON: options });
+      const { user, passkeyId } = await api('POST', '/api/passkeys/verify', { response });
+      state.highlightPasskeyId = passkeyId;
+      setUser(user);
+      showNotice('Passkey created. You can now use it to sign in.');
+      signalAccountState();
+    } catch (err) {
+      reportAccountError(err);
+    }
+  }
+
+  els.addPasskey.addEventListener('click', () => busy(els.addPasskey, addPasskey));
+
+  function confirmRemoval(passkey) {
+    els.confirmMessage.textContent =
+      `You won’t be able to sign in with “${passkey.name}” anymore. Other devices signed in to your ` +
+      'account will be signed out. You may also want to delete it from your device or password manager.';
+    els.confirmDialog.returnValue = '';
+    els.confirmDialog.showModal();
+    return new Promise((resolve) => {
+      els.confirmDialog.addEventListener(
+        'close',
+        () => resolve(els.confirmDialog.returnValue === 'confirm'),
+        { once: true },
+      );
+    });
+  }
+
+  async function removePasskey(passkey) {
+    clearNotice();
+    if (!(await confirmRemoval(passkey))) return;
+    try {
+      const path = `/api/passkeys/${encodeURIComponent(passkey.id)}`;
+      const { user } = await withReauth(
+        () => api('DELETE', path),
+        `To remove “${passkey.name}”, please verify with one of your passkeys.`,
+      );
+      setUser(user);
+      showNotice(`“${passkey.name}” was removed from your account.`);
+      // Ask the passkey provider to hide the removed passkey.
+      signalAccountState();
+    } catch (err) {
+      reportAccountError(err);
+    }
+  }
+
+  function startRename(item, passkey) {
+    const form = $('.rename-form', item);
+    $('.passkey-name', item).hidden = true;
+    $('.passkey-actions', item).hidden = true;
+    form.hidden = false;
+    form.elements.name.value = passkey.name;
+    form.elements.name.select();
+  }
+
+  function cancelRename(item) {
+    $('.rename-form', item).hidden = true;
+    $('.passkey-name', item).hidden = false;
+    $('.passkey-actions', item).hidden = false;
+    $('[data-action="rename"]', item).focus();
+  }
+
+  async function renamePasskey(form, passkey) {
+    const name = form.elements.name.value.trim();
+    if (!name) return form.elements.name.focus();
+    if (name === passkey.name) return cancelRename(form.closest('.passkey-item'));
+    try {
+      const { user } = await api('PATCH', `/api/passkeys/${encodeURIComponent(passkey.id)}`, { name });
+      setUser(user);
+      showNotice('Passkey renamed.');
+    } catch (err) {
+      reportAccountError(err);
+    }
+  }
+
+  function passkeyFor(item) {
+    return state.user?.passkeys.find((p) => p.id === item?.dataset.id);
+  }
+
+  els.passkeyList.addEventListener('click', (event) => {
+    const button = event.target.closest('button[data-action]');
+    const item = button?.closest('.passkey-item');
+    const passkey = passkeyFor(item);
+    if (!passkey) return;
+
+    switch (button.dataset.action) {
+      case 'rename':
+        startRename(item, passkey);
+        break;
+      case 'cancel-rename':
+        cancelRename(item);
+        break;
+      case 'remove':
+        busy(button, () => removePasskey(passkey));
+        break;
+    }
+  });
+
+  els.passkeyList.addEventListener('submit', (event) => {
+    event.preventDefault();
+    const form = event.target;
+    const passkey = passkeyFor(form.closest('.passkey-item'));
+    if (passkey) busy(event.submitter || $('button[type="submit"]', form), () => renamePasskey(form, passkey));
+  });
+
+  els.passkeyList.addEventListener('keydown', (event) => {
+    if (event.key === 'Escape' && event.target.closest('.rename-form')) {
+      cancelRename(event.target.closest('.passkey-item'));
+    }
+  });
+
+  /* --------------------------------------------------------------------------------------------
+   * Sign out
+   * ------------------------------------------------------------------------------------------ */
+
+  els.signout.addEventListener('click', () => busy(els.signout, async () => {
+    try {
+      await api('POST', '/api/logout', {});
+    } catch {
+      // Signing out locally is still the right outcome.
+    }
+    state.highlightPasskeyId = null;
+    setUser(null);
+    showNotice('You’ve been signed out. See you soon!');
+    startAutofillSignIn();
+  }));
+
+  /* --------------------------------------------------------------------------------------------
+   * Startup
+   * ------------------------------------------------------------------------------------------ */
+
+  async function init() {
+    if (!browserSupportsWebAuthn()) {
+      els.loading.hidden = true;
+      els.unsupported.hidden = false;
+      for (const form of [els.signinForm, els.registerForm]) {
+        for (const control of form.elements) control.disabled = true;
+      }
+    }
+
+    try {
+      const session = await api('GET', '/api/session');
+      state.rpID = session.rpID;
+      setUser(session.user);
+    } catch (err) {
+      els.loading.hidden = true;
+      return reportError(err);
+    }
+
+    if (state.user) signalAccountState();
+    else if (browserSupportsWebAuthn()) startAutofillSignIn();
+  }
+
+  init();
+})();
diff --git a/public/assets/nav.js b/public/assets/nav.js
new file mode 100644
index 0000000..0410b96
--- /dev/null
+++ b/public/assets/nav.js
@@ -0,0 +1,43 @@
+// Keeps the site navigation in sync with the customer's sign-in state and signs out via POST.
+(() => {
+  let signedIn = false;
+
+  function render() {
+    const link = document.querySelector('[data-auth-link]');
+    if (!link) return;
+    link.textContent = signedIn ? 'Logout' : 'Sign in';
+    link.href = signedIn ? '/logout' : '/account';
+  }
+
+  async function signOut() {
+    await fetch('/api/logout', {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: '{}',
+    });
+    window.location.assign('/');
+  }
+
+  document.addEventListener('click', (event) => {
+    const link = event.target.closest('[data-auth-link]');
+    if (!link || !signedIn) return;
+    event.preventDefault();
+    signOut().catch(() => window.location.assign('/account'));
+  });
+
+  window.DailyGrindNav = {
+    setSignedIn(value) {
+      signedIn = Boolean(value);
+      render();
+    },
+    signOut,
+  };
+
+  // The account page manages its own session state and reports it via setSignedIn().
+  if (document.body.dataset.page !== 'account') {
+    fetch('/api/session', { headers: { Accept: 'application/json' } })
+      .then((res) => (res.ok ? res.json() : null))
+      .then((data) => window.DailyGrindNav.setSignedIn(Boolean(data?.user)))
+      .catch(() => {});
+  }
+})();
diff --git a/public/assets/site.css b/public/assets/site.css
