new file mode 100644
index 0000000..9708430
--- /dev/null
+++ b/server/static.js
@@ -0,0 +1,94 @@
+import fs from 'node:fs/promises';
+import path from 'node:path';
+import { config } from './config.js';
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.js': 'text/javascript; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.svg': 'image/svg+xml',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.ico': 'image/x-icon',
+  '.webp': 'image/webp',
+};
+
+const CSP = [
+  "default-src 'self'",
+  "script-src 'self'",
+  // The homepage uses an inline <style> block and style attributes.
+  "style-src 'self' 'unsafe-inline'",
+  "img-src 'self' data: https://images.unsplash.com",
+  "connect-src 'self'",
+  "object-src 'none'",
+  "base-uri 'none'",
+  "form-action 'self'",
+  "frame-ancestors 'none'",
+].join('; ');
+
+export function setSecurityHeaders(res) {
+  res.setHeader('Content-Security-Policy', CSP);
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
+  res.setHeader('Cross-Origin-Opener-Policy', 'same-origin');
+  if (config.secureCookies) {
+    res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
+  }
+}
+
+async function tryFile(file) {
+  try {
+    const stat = await fs.stat(file);
+    return stat.isFile() ? file : null;
+  } catch {
+    return null;
+  }
+}
+
+/** Resolves a URL path to a file inside public/, supporting extensionless URLs like /account. */
+async function resolvePublicFile(pathname) {
+  let decoded;
+  try {
+    decoded = decodeURIComponent(pathname);
+  } catch {
+    return null;
+  }
+  if (decoded.includes('\0')) return null;
+  const base = path.join(config.publicDir, path.normalize(decoded));
+  if (base !== config.publicDir && !base.startsWith(config.publicDir + path.sep)) return null;
+
+  if (decoded.endsWith('/')) return tryFile(path.join(base, 'index.html'));
+  return (await tryFile(base)) || (path.extname(base) ? null : tryFile(`${base}.html`));
+}
+
+export async function serveStatic(req, res, url) {
+  if (req.method !== 'GET' && req.method !== 'HEAD') {
+    res.writeHead(405, { Allow: 'GET, HEAD' });
+    res.end();
+    return;
+  }
+
+  // Signing out is a state change, so it's done with a POST from the account UI. Plain links to
+  // /logout land on the account page where the customer can sign out.
+  if (url.pathname === '/logout') {
+    res.writeHead(303, { Location: '/account' });
+    res.end();
+    return;
+  }
+
+  const file = config.vendorFiles[url.pathname] || (await resolvePublicFile(url.pathname));
+  if (!file) {
+    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Not found');
+    return;
+  }
+
+  const body = await fs.readFile(file);
+  res.writeHead(200, {
+    'Content-Type': MIME_TYPES[path.extname(file)] || 'application/octet-stream',
+    'Content-Length': body.length,
+    'Cache-Control': file.endsWith('.html') ? 'no-cache' : 'public, max-age=300',
+  });
+  res.end(req.method === 'HEAD' ? undefined : body);
+}
diff --git a/server/store.js b/server/store.js
new file mode 100644
index 0000000..a128bf7
--- /dev/null
+++ b/server/store.js
@@ -0,0 +1,64 @@
+import fs from 'node:fs/promises';
+import path from 'node:path';
+
+/**
+ * Tiny JSON-file persistence for customer accounts and their passkeys. Writes are serialized and
+ * atomic (write to temp file, then rename) so a crash can't leave a half-written database.
+ *
+ * User shape:
+ * {
+ *   id, webauthnUserID, email, name, createdAt, updatedAt,
+ *   passkeys: [{ id, publicKey, counter, transports, deviceType, backedUp, aaguid, name,
+ *                createdAt, lastUsedAt }]
+ * }
+ */
+export class Store {
+  constructor(file) {
+    this.file = file;
+    this.data = { users: [] };
+    this.writeQueue = Promise.resolve();
+  }
+
+  async load() {
+    try {
+      this.data = JSON.parse(await fs.readFile(this.file, 'utf8'));
+      this.data.users ??= [];
+    } catch (err) {
+      if (err.code !== 'ENOENT') throw err;
+      await this.save();
+    }
+  }
+
+  save() {
+    const snapshot = JSON.stringify(this.data, null, 2);
+    this.writeQueue = this.writeQueue.then(async () => {
+      await fs.mkdir(path.dirname(this.file), { recursive: true });
+      const tmp = `${this.file}.${process.pid}.tmp`;
+      await fs.writeFile(tmp, snapshot, { mode: 0o600 });
+      await fs.rename(tmp, this.file);
+    });
+    return this.writeQueue;
+  }
+
+  getUserById(id) {
+    return this.data.users.find((u) => u.id === id);
+  }
+
+  getUserByEmail(email) {
+    return this.data.users.find((u) => u.email === email);
+  }
+
+  findPasskey(credentialID) {
+    for (const user of this.data.users) {
+      const passkey = user.passkeys.find((p) => p.id === credentialID);
+      if (passkey) return { user, passkey };
+    }
+    return null;
+  }
+
+  async createUser(user) {
+    this.data.users.push(user);
+    await this.save();
+    return user;
+  }
+}
diff --git a/test/passkeys.test.js b/test/passkeys.test.js
new file mode 100644
index 0000000..1f12480
--- /dev/null
+++ b/test/passkeys.test.js
@@ -0,0 +1,481 @@
+import { after, before, describe, test } from 'node:test';
+import assert from 'node:assert/strict';
+import crypto from 'node:crypto';
+import fs from 'node:fs/promises';
+import os from 'node:os';
+import path from 'node:path';
+import { Readable } from 'node:stream';
+import { isoBase64URL, isoCBOR } from '@simplewebauthn/server/helpers';
+
+const tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), 'daily-grind-test-'));
+process.env.DATA_FILE = path.join(tmpDir, 'db.json');
+delete process.env.ORIGIN;
+delete process.env.RP_ID;
+
+const { config } = await import('../server/config.js');
+const { Store } = await import('../server/store.js');
+const { createApi } = await import('../server/api.js');
+const { serveStatic } = await import('../server/static.js');
+
+const ORIGIN = config.origin;
+const sha256 = (data) => crypto.createHash('sha256').update(data).digest();
+const b64url = (buf) => isoBase64URL.fromBuffer(new Uint8Array(buf));
+
+/* ------------------------------------------------------------------------------------------------
+ * A minimal software authenticator (ES256, "none" attestation) acting like a synced passkey provider.
+ * ---------------------------------------------------------------------------------------------- */
+
+class SoftAuthenticator {
+  constructor({ aaguid = 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4', origin = ORIGIN } = {}) {
+    this.aaguid = Buffer.from(aaguid.replaceAll('-', ''), 'hex');
+    this.origin = origin;
+    this.credentials = []; // { id, privateKey, userHandle, rpId, counter }
+  }
+
+  authData(rpId, flags, counter, attested) {
+    const counterBuf = Buffer.alloc(4);
+    counterBuf.writeUInt32BE(counter);
+    return Buffer.concat([sha256(rpId), Buffer.from([flags]), counterBuf, attested ?? Buffer.alloc(0)]);
+  }
+
+  create(options) {
+    const excluded = new Set((options.excludeCredentials ?? []).map((c) => c.id));
+    if (this.credentials.some((c) => excluded.has(c.id))) {
+      throw Object.assign(new Error('excluded'), { name: 'InvalidStateError' });
+    }
+    const { privateKey, publicKey } = crypto.generateKeyPairSync('ec', { namedCurve: 'P-256' });
+    const jwk = publicKey.export({ format: 'jwk' });
+    const credId = crypto.randomBytes(16);
+    const cose = isoCBOR.encode(new Map([
+      [1, 2], [3, -7], [-1, 1],
+      [-2, new Uint8Array(Buffer.from(jwk.x, 'base64url'))],
+      [-3, new Uint8Array(Buffer.from(jwk.y, 'base64url'))],
+    ]));
+    const idLen = Buffer.alloc(2);
+    idLen.writeUInt16BE(credId.length);
+    const attested = Buffer.concat([this.aaguid, idLen, credId, Buffer.from(cose)]);
+    // UP | UV | BE | BS | AT
+    const authData = this.authData(options.rp.id, 0x01 | 0x04 | 0x08 | 0x10 | 0x40, 0, attested);
+    const clientDataJSON = Buffer.from(JSON.stringify({
+      type: 'webauthn.create', challenge: options.challenge, origin: this.origin, crossOrigin: false,
+    }));
+    const attestationObject = isoCBOR.encode(new Map([
+      ['fmt', 'none'], ['attStmt', new Map()], ['authData', new Uint8Array(authData)],
+    ]));
+    const id = b64url(credId);
+    this.credentials.push({ id, privateKey, userHandle: options.user.id, rpId: options.rp.id, counter: 0 });
+    return {
+      id,
+      rawId: id,
+      type: 'public-key',
+      response: {
+        clientDataJSON: b64url(clientDataJSON),
+        attestationObject: b64url(attestationObject),
+        transports: ['hybrid', 'internal'],
+      },
+      clientExtensionResults: { credProps: { rk: true } },
+    };
+  }
+
+  get(options, credentialId) {
+    const allowed = (options.allowCredentials ?? []).map((c) => c.id);
+    const cred = credentialId
+      ? this.credentials.find((c) => c.id === credentialId)
+      : this.credentials.find((c) => !allowed.length || allowed.includes(c.id));
+    if (!cred) throw Object.assign(new Error('no credential'), { name: 'NotAllowedError' });
+    cred.counter += 1;
+    const authData = this.authData(options.rpId, 0x01 | 0x04 | 0x08 | 0x10, cred.counter);
+    const clientDataJSON = Buffer.from(JSON.stringify({
+      type: 'webauthn.get', challenge: options.challenge, origin: this.origin, crossOrigin: false,
+    }));
+    const signature = crypto.sign('sha256', Buffer.concat([authData, sha256(clientDataJSON)]), cred.privateKey);
+    return {
+      id: cred.id,
+      rawId: cred.id,
+      type: 'public-key',
+      response: {
+        clientDataJSON: b64url(clientDataJSON),
+        authenticatorData: b64url(authData),
+        signature: b64url(signature),
+        userHandle: cred.userHandle,
+      },
+      clientExtensionResults: {},
+    };
+  }
+}
+
+/* ------------------------------------------------------------------------------------------------
+ * In-process HTTP client (no listening server) that keeps a cookie jar.
+ * ---------------------------------------------------------------------------------------------- */
+
+let store;
+let api;
+let ipCounter = 0;
+
+class Client {
+  constructor() {
+    this.cookie = '';
+    this.ip = `10.0.0.${++ipCounter}`;
+  }
+
+  async request(method, pathname, body, { origin = ORIGIN, contentType = 'application/json' } = {}) {
+    const payload = body === undefined ? [] : [Buffer.from(JSON.stringify(body))];
+    const req = Readable.from(payload);
+    Object.assign(req, {
+      method,
+      url: pathname,
+      headers: {
+        ...(this.cookie && { cookie: this.cookie }),
+        ...(origin && { origin }),
+        ...(body !== undefined && { 'content-type': contentType }),
+      },
+      socket: { remoteAddress: this.ip },
+    });
+
+    const headers = {};
+    let status = 200;
+    let raw = '';
+    const res = {
+      headersSent: false,
+      setHeader: (k, v) => { headers[k.toLowerCase()] = v; },
+      writeHead: (s, h = {}) => {
+        status = s;
+        for (const [k, v] of Object.entries(h)) headers[k.toLowerCase()] = v;
+        res.headersSent = true;
+      },
+      end: (chunk) => { if (chunk) raw += chunk; },
+    };
+
+    const url = new URL(pathname, ORIGIN);
+    if (url.pathname.startsWith('/api/')) await api(req, res, url);
+    else await serveStatic(req, res, url);
+
+    const setCookie = headers['set-cookie'];
+    if (setCookie) {
+      const pair = setCookie.split(';')[0];
+      this.cookie = /Max-Age=0\b/.test(setCookie) ? '' : pair;
+    }
+    let data = raw;
+    try { data = JSON.parse(raw); } catch { /* not JSON */ }
+    return { status, data, headers };
+  }
+
+  async register(authenticator, { name = 'Ada Lovelace', email = 'ada@example.com' } = {}) {
+    const opts = await this.request('POST', '/api/register/options', { name, email });
+    assert.equal(opts.status, 200, JSON.stringify(opts.data));
+    const response = authenticator.create(opts.data.options);
+    return this.request('POST', '/api/register/verify', { response });
+  }
+
+  async login(authenticator, credentialId) {
+    const opts = await this.request('POST', '/api/login/options', {});
+    assert.equal(opts.status, 200);
+    return this.request('POST', '/api/login/verify', { response: authenticator.get(opts.data.options, credentialId) });
+  }
+
+  async reauth(authenticator, credentialId) {
+    const opts = await this.request('POST', '/api/reauth/options', {});
+    assert.equal(opts.status, 200, JSON.stringify(opts.data));
+    return this.request('POST', '/api/reauth/verify', { response: authenticator.get(opts.data.options, credentialId) });
+  }
+
+  async addPasskey(authenticator) {
+    const opts = await this.request('POST', '/api/passkeys/options', {});
+    if (opts.status !== 200) return opts;
+    return this.request('POST', '/api/passkeys/verify', { response: authenticator.create(opts.data.options) });
+  }
+}
+
+/** Runs `fn` with sensitive-action reauthentication treated as stale. */
+async function withStaleAuth(fn) {
+  const original = config.reauthWindow;
+  config.reauthWindow = -1;
+  try {
+    return await fn();
+  } finally {
+    config.reauthWindow = original;
+  }
+}
+
+before(async () => {
+  store = new Store(config.dataFile);
+  await store.load();
+  api = createApi(store);
+});
+
+after(async () => {
+  await store.writeQueue;
+  await fs.rm(tmpDir, { recursive: true, force: true });
+});
+
+/* ------------------------------------------------------------------------------------------------
+ * Tests
+ * ---------------------------------------------------------------------------------------------- */
+
+describe('registration', () => {
+  test('creates an account with a passkey and signs the customer in', async () => {
+    const client = new Client();
+    const auth = new SoftAuthenticator();
+
+    const opts = await client.request('POST', '/api/register/options', { name: ' Ada  Lovelace ', email: 'ADA@Example.com ' });
+    assert.equal(opts.status, 200);
+    const { options } = opts.data;
+    assert.equal(options.rp.id, 'localhost');
+    assert.equal(options.user.name, 'ada@example.com');
+    assert.equal(options.user.displayName, 'Ada Lovelace');
+    assert.equal(options.authenticatorSelection.residentKey, 'required');
+    assert.equal(options.authenticatorSelection.userVerification, 'required');
+
+    const res = await client.request('POST', '/api/register/verify', { response: auth.create(options) });
+    assert.equal(res.status, 200, JSON.stringify(res.data));
+    assert.equal(res.data.user.email, 'ada@example.com');
+    assert.equal(res.data.user.passkeys.length, 1);
+    assert.equal(res.data.user.passkeys[0].name, 'Google Password Manager');
+    assert.equal(res.data.user.passkeys[0].synced, true);
+    assert.ok(res.data.user.reauthValidUntil > Date.now());
+    assert.equal('publicKey' in res.data.user.passkeys[0], false, 'public keys are not exposed');
+
+    const session = await client.request('GET', '/api/session');
+    assert.equal(session.data.user.name, 'Ada Lovelace');
+    assert.equal(session.data.rpID, 'localhost');
+  });
+
+  test('rejects duplicate emails and invalid input', async () => {
+    const client = new Client();
+    const dup = await client.request('POST', '/api/register/options', { name: 'Ada', email: 'ada@example.com' });
+    assert.equal(dup.status, 409);
+    assert.equal(dup.data.error, 'email_taken');
+
+    const badEmail = await client.request('POST', '/api/register/options', { name: 'X', email: 'nope' });
+    assert.equal(badEmail.data.error, 'invalid_email');
+
+    const noName = await client.request('POST', '/api/register/options', { name: '   ', email: 'x@example.com' });
+    assert.equal(noName.data.error, 'invalid_name');
+  });
+
+  test('rejects responses from the wrong origin and replayed challenges', async () => {
+    const client = new Client();
+    const phish = new SoftAuthenticator({ origin: 'https://daily-grind.evil' });
+    const opts = await client.request('POST', '/api/register/options', { name: 'Eve', email: 'eve@example.com' });
+    const response = phish.create(opts.data.options);
+    const res = await client.request('POST', '/api/register/verify', { response });
+    assert.equal(res.status, 400);
+    assert.equal(res.data.error, 'verification_failed');
+
+    // The challenge was consumed by the failed attempt.
+    const replay = await client.request('POST', '/api/register/verify', { response });
+    assert.equal(replay.data.error, 'challenge_expired');
+    assert.equal(store.getUserByEmail('eve@example.com'), undefined);
+  });
+});
+
+describe('sign in', () => {
+  test('signs in with a discoverable passkey and rotates the session', async () => {
+    const auth = new SoftAuthenticator();
+    const signup = new Client();
+    await signup.register(auth, { name: 'Grace', email: 'grace@example.com' });
+
+    const client = new Client();
+    const opts = await client.request('POST', '/api/login/options', {});
+    assert.deepEqual(opts.data.options.allowCredentials ?? [], []);
+    assert.equal(opts.data.options.userVerification, 'required');
+    const anonymousCookie = client.cookie;
+
+    const res = await client.request('POST', '/api/login/verify', { response: auth.get(opts.data.options) });
+    assert.equal(res.status, 200, JSON.stringify(res.data));
+    assert.equal(res.data.user.email, 'grace@example.com');
+    assert.notEqual(client.cookie, anonymousCookie, 'session id rotates on sign-in');
+    assert.equal(store.getUserByEmail('grace@example.com').passkeys[0].counter, 1);
+  });
+
+  test('reports unknown passkeys so the browser can hide them', async () => {
+    const auth = new SoftAuthenticator();
+    const opts = await new Client().request('POST', '/api/register/options', { name: 'X', email: 'ghost@example.com' });
+    auth.create(opts.data.options); // never verified, so the server doesn't know it
+
+    const res = await new Client().login(auth);
+    assert.equal(res.status, 400);
+    assert.equal(res.data.error, 'unknown_credential');
+    assert.equal(res.data.credentialID, auth.credentials[0].id);
+  });
+
+  test('rejects a reused challenge and a cloned authenticator counter', async () => {
+    const auth = new SoftAuthenticator();
+    await new Client().register(auth, { name: 'Linus', email: 'linus@example.com' });
+
+    const client = new Client();
+    const opts = await client.request('POST', '/api/login/options', {});
+    const response = auth.get(opts.data.options);
+    assert.equal((await client.request('POST', '/api/login/verify', { response })).status, 200);
+
+    const replay = await client.request('POST', '/api/login/verify', { response });
+    assert.equal(replay.data.error, 'challenge_expired');
+
+    auth.credentials[0].counter = 0; // a clone with a stale counter
+    const cloned = await new Client().login(auth);
+    assert.equal(cloned.data.error, 'verification_failed');
+  });
+
+  test('sign out ends the session', async () => {
+    const auth = new SoftAuthenticator();
+    const client = new Client();
+    await client.register(auth, { name: 'Ken', email: 'ken@example.com' });
+    assert.equal((await client.request('POST', '/api/logout', {})).status, 200);
+    assert.equal((await client.request('GET', '/api/session')).data.user, null);
+  });
+});
+
+describe('account management', () => {
+  test('updates the name freely but requires reauthentication to change email', async () => {
+    const auth = new SoftAuthenticator();
+    const client = new Client();
+    await client.register(auth, { name: 'Margaret', email: 'margaret@example.com' });
+    await new Client().register(new SoftAuthenticator(), { name: 'Other', email: 'taken@example.com' });
+
+    await withStaleAuth(async () => {
+      const rename = await client.request('PATCH', '/api/profile', { name: 'Margaret Hamilton', email: 'margaret@example.com' });
+      assert.equal(rename.status, 200);
+      assert.equal(rename.data.user.name, 'Margaret Hamilton');
+
+      const change = await client.request('PATCH', '/api/profile', { email: 'mh@example.com' });
+      assert.equal(change.status, 403);
+      assert.equal(change.data.error, 'reauth_required');
+    });
+
+    assert.equal((await client.reauth(auth)).status, 200);
+    const taken = await client.request('PATCH', '/api/profile', { email: 'taken@example.com' });
+    assert.equal(taken.data.error, 'email_taken');
+    const change = await client.request('PATCH', '/api/profile', { email: 'MH@example.com' });
+    assert.equal(change.status, 200);
+    assert.equal(change.data.user.email, 'mh@example.com');
+  });
+
+  test('adds, renames, and removes passkeys with reauthentication', async () => {
+    const phone = new SoftAuthenticator();
+    const laptop = new SoftAuthenticator({ aaguid: 'bada5566-a7aa-401f-bd96-45619a55120d' });
+    const client = new Client();
+    const signup = await client.register(phone, { name: 'Barbara', email: 'barbara@example.com' });
+    const phoneId = signup.data.user.passkeys[0].id;
+
+    const lastOne = await client.request('DELETE', `/api/passkeys/${phoneId}`);
+    assert.equal(lastOne.status, 409);
+    assert.equal(lastOne.data.error, 'last_passkey');
+
+    const stale = await withStaleAuth(() => client.addPasskey(laptop));
+    assert.equal(stale.data.error, 'reauth_required');
+
+    // Re-registering a provider that already has a passkey for this account is excluded.
+    const excluded = await client.request('POST', '/api/passkeys/options', {});
+    assert.deepEqual(excluded.data.options.excludeCredentials.map((c) => c.id), [phoneId]);
+    assert.throws(() => phone.create(excluded.data.options), { name: 'InvalidStateError' });
+
+    const added = await client.addPasskey(laptop);
+    assert.equal(added.status, 200, JSON.stringify(added.data));
+    assert.equal(added.data.user.passkeys.length, 2);
+    const laptopKey = added.data.user.passkeys.find((p) => p.id === added.data.passkeyId);
+    assert.equal(laptopKey.name, '1Password');
+
+    const renamed = await client.request('PATCH', `/api/passkeys/${laptopKey.id}`, { name: '  Work laptop ' });
+    assert.equal(renamed.data.user.passkeys.find((p) => p.id === laptopKey.id).name, 'Work laptop');
+    const blank = await client.request('PATCH', `/api/passkeys/${laptopKey.id}`, { name: '' });
+    assert.equal(blank.data.error, 'invalid_passkey_name');
+
+    // Another device stays signed in until a passkey is removed.
+    const otherDevice = new Client();
+    assert.equal((await otherDevice.login(laptop)).status, 200);
+
+    const staleDelete = await withStaleAuth(() => client.request('DELETE', `/api/passkeys/${phoneId}`));
+    assert.equal(staleDelete.data.error, 'reauth_required');
+
+    assert.equal((await client.reauth(laptop)).status, 200);
+    const removed = await client.request('DELETE', `/api/passkeys/${phoneId}`);
+    assert.equal(removed.status, 200);
+    assert.deepEqual(removed.data.user.passkeys.map((p) => p.id), [laptopKey.id]);
+    assert.equal((await otherDevice.request('GET', '/api/session')).data.user, null);
+
+    const signInWithRemoved = await new Client().login(phone);
+    assert.equal(signInWithRemoved.data.error, 'unknown_credential');
+  });
+
+  test('reauthentication only accepts the signed-in customer’s passkeys', async () => {
+    const mine = new SoftAuthenticator();
+    const theirs = new SoftAuthenticator();
+    const client = new Client();
+    await client.register(mine, { name: 'Me', email: 'me@example.com' });
+    await new Client().register(theirs, { name: 'Them', email: 'them@example.com' });
+
+    const opts = await client.request('POST', '/api/reauth/options', {});
+    assert.equal(opts.data.options.allowCredentials.length, 1);
+    const res = await client.request('POST', '/api/reauth/verify', {
+      response: theirs.get(opts.data.options, theirs.credentials[0].id),
+    });
+    assert.equal(res.data.error, 'unknown_credential');
+  });
+
+  test('cannot manage another customer’s passkeys', async () => {
+    const victimAuth = new SoftAuthenticator();
+    const victim = new Client();
+    const v = await victim.register(victimAuth, { name: 'Victim', email: 'victim@example.com' });
+    const attacker = new Client();
+    await attacker.register(new SoftAuthenticator(), { name: 'Mallory', email: 'mallory@example.com' });
+
+    const res = await attacker.request('PATCH', `/api/passkeys/${v.data.user.passkeys[0].id}`, { name: 'pwned' });
+    assert.equal(res.status, 404);
+  });
+});
+
+describe('request protections', () => {
+  test('requires sign-in for account routes', async () => {
+    const client = new Client();
+    for (const [method, url, body] of [
+      ['PATCH', '/api/profile', { name: 'x' }],
+      ['POST', '/api/passkeys/options', {}],
+      ['POST', '/api/reauth/options', {}],
+      ['DELETE', '/api/passkeys/abc'],
+    ]) {
+      const res = await client.request(method, url, body);
+      assert.equal(res.status, 401, `${method} ${url}`);
+    }
+  });
+
+  test('blocks cross-site and non-JSON requests', async () => {
+    const auth = new SoftAuthenticator();
+    const client = new Client();
+    await client.register(auth, { name: 'Csrf', email: 'csrf@example.com' });
+
+    const crossSite = await client.request('PATCH', '/api/profile', { name: 'Hacked' }, { origin: 'https://evil.example' });
+    assert.equal(crossSite.status, 403);
+    assert.equal(crossSite.data.error, 'bad_origin');
+
+    const noOrigin = await client.request('POST', '/api/logout', {}, { origin: null });
+    assert.equal(noOrigin.status, 403);
+
+    const form = await client.request('PATCH', '/api/profile', { name: 'Hacked' }, { contentType: 'text/plain' });
+    assert.equal(form.status, 415);
+    assert.equal(store.getUserByEmail('csrf@example.com').name, 'Csrf');
+  });
+
+  test('rate limits ceremony endpoints', async () => {
+    const client = new Client();
+    let last;
+    for (let i = 0; i < 31; i++) last = await client.request('POST', '/api/login/options', {});
+    assert.equal(last.status, 429);
+  });
+});
+
+describe('static pages', () => {
+  test('serves the account page at /account', async () => {
+    const res = await new Client().request('GET', '/account');
+    assert.equal(res.status, 200);
+    assert.match(res.headers['content-type'], /text\/html/);
+    assert.match(res.data, /Create account with a passkey/);
+  });
+
+  test('serves the browser library and blocks paths outside public/', async () => {
+    const client = new Client();
+    assert.equal((await client.request('GET', '/vendor/simplewebauthn-browser.js')).status, 200);
+    for (const p of ['/../package.json', '/%2e%2e/server/api.js', '/..%2fdata%2fdb.json']) {
+      assert.equal((await client.request('GET', p)).status, 404, p);
+    }
+  });
+});

