+import type { APIRoute } from 'astro';
+import { generateAuthenticationOptions } from '@simplewebauthn/server';
+import { getRpId } from '../../../../lib/auth/config';
+import { json } from '../../../../lib/auth/session';
+
+/** Discoverable-credential sign-in options (used by both autofill and the explicit button). */
+export const POST: APIRoute = async ({ session, url }) => {
+  const options = await generateAuthenticationOptions({
+    rpID: getRpId(url),
+    allowCredentials: [],
+    userVerification: 'preferred',
+  });
+  session?.set('authentication', { challenge: options.challenge, userVerification: 'preferred' });
+  return json(options);
+};
