@@ -0,0 +1,40 @@
+import type { APIRoute } from 'astro';
+import { generateRegistrationOptions } from '@simplewebauthn/server';
+import { isoBase64URL } from '@simplewebauthn/server/helpers';
+import { getRpId, RP_NAME } from '../../../../lib/auth/config';
+import { findCredentialsByUserId } from '../../../../lib/auth/store';
+import { getSessionUser, json } from '../../../../lib/auth/session';
+
+/**
+ * Body flags:
+ * - promotion: offered right after sign-up/sign-in — restrict to platform authenticators.
+ * - conditional: silent post-password-login creation (conditional create).
+ * Management flows send neither so security keys are allowed too.
+ */
+export const POST: APIRoute = async ({ request, session, url }) => {
+  const user = await getSessionUser(session);
+  if (!user) return json({ error: 'Not signed in' }, 401);
+
+  const { promotion = false, conditional = false } = await request.json().catch(() => ({}));
+  const existing = await findCredentialsByUserId(user.id);
+
+  const options = await generateRegistrationOptions({
+    rpName: RP_NAME,
+    rpID: getRpId(url),
+    userID: isoBase64URL.toBuffer(user.id),
+    userName: user.username,
+    userDisplayName: user.displayName,
+    attestationType: 'none',
+    supportedAlgorithmIDs: [-7, -257],
+    excludeCredentials: existing.map((cred) => ({ id: cred.id, transports: cred.transports })),
+    authenticatorSelection: {
+      residentKey: 'required',
+      requireResidentKey: true,
+      userVerification: 'preferred',
+      ...((promotion || conditional) && { authenticatorAttachment: 'platform' as const }),
+    },
+  });
+
+  session?.set('registration', { challenge: options.challenge, conditional: Boolean(conditional) });
+  return json(options);
+};
