+  background: none;
+  border: none;
+  color: var(--text);
+  font: inherit;
+  font-size: 0.85rem;
+  margin: 0 10px;
+  cursor: pointer;
+}
+
+.link-button:hover,
+.footer-links a:hover {
+  text-decoration: underline;
+}
+
+/* Privacy choices dialog */
+.privacy-dialog {
+  max-width: 480px;
+  width: calc(100% - 40px);
+  margin: auto;
+  border: none;
+  border-radius: 8px;
+  padding: 24px;
+  color: var(--text);
+  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
+}
+
+.privacy-dialog::backdrop {
+  background: rgba(0, 0, 0, 0.5);
+}
+
+.privacy-dialog h2 {
+  color: var(--primary);
+  margin-bottom: 10px;
+}
+
+.privacy-dialog p,
+.privacy-dialog fieldset {
+  margin-bottom: 15px;
+  font-size: 0.9rem;
+}
+
+.privacy-dialog fieldset {
+  border: 1px solid var(--secondary);
+  border-radius: 6px;
+  padding: 12px;
+}
+
+.privacy-dialog label {
+  display: flex;
+  gap: 10px;
+  align-items: flex-start;
+}
+
+.privacy-dialog label + label {
+  margin-top: 10px;
+}
+
+.privacy-dialog input[type="checkbox"] {
+  margin-top: 5px;
+}
+
+.privacy-notice {
+  background: #fff3e0;
+  border-left: 4px solid var(--accent);
+  padding: 8px 12px;
+}
+
+.privacy-status {
+  min-height: 1.6em;
+  font-weight: bold;
+}
+
+.dialog-actions {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 10px;
+  justify-content: flex-end;
+}
+
+.dialog-actions .btn {
+  margin-top: 0;
+  border: none;
+  font: inherit;
+  cursor: pointer;
+}
+
+.btn-secondary {
+  background: var(--secondary);
+  color: var(--text);
+}
+
+.btn-secondary:hover {
+  background: #bcaaa4;
+}
+
+[hidden] {
+  display: none !important;
+}
