+// Zero-dependency static server for The Daily Grind.
+// Serves only ./public, sends hardened security/privacy headers, and keeps no request logs.
+import { createServer } from 'node:http';
+import { createReadStream } from 'node:fs';
+import { stat } from 'node:fs/promises';
+import { extname, join, resolve, sep } from 'node:path';
+import { fileURLToPath } from 'node:url';
+
+const ROOT = resolve(fileURLToPath(new URL('./public', import.meta.url)));
+const PORT = Number(process.env.PORT) || 11222;
+// Like statikk, stay on localhost unless explicitly exposed (e.g. behind a TLS-terminating proxy).
+const HOST = process.env.HOST || 'localhost';
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.js': 'text/javascript; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.txt': 'text/plain; charset=utf-8',
+  '.svg': 'image/svg+xml',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.jpeg': 'image/jpeg',
+  '.webp': 'image/webp',
+  '.avif': 'image/avif',
+  '.ico': 'image/x-icon',
+  '.woff2': 'font/woff2',
+};
+
+// Every resource is first-party, so the policy allows 'self' only. If a third party is ever added,
+// it must go through the audit in PRIVACY.md and scripts/audit-third-parties.mjs first.
+const CONTENT_SECURITY_POLICY = [
+  "default-src 'none'",
+  "script-src 'self'",
+  "style-src 'self'",
+  "img-src 'self'",
+  "font-src 'self'",
+  "connect-src 'self'",
+  "manifest-src 'self'",
+  "form-action 'self'",
+  "frame-ancestors 'none'",
+  "base-uri 'none'",
+  "object-src 'none'",
+  "require-trusted-types-for 'script'",
+  "trusted-types 'none'",
+  'upgrade-insecure-requests',
+].join('; ');
+
+const PERMISSIONS_POLICY = [
+  'accelerometer=()',
+  'ambient-light-sensor=()',
+  'autoplay=()',
+  'bluetooth=()',
+  'browsing-topics=()',
+  'camera=()',
+  'display-capture=()',
+  'encrypted-media=()',
+  'geolocation=()',
+  'gyroscope=()',
+  'hid=()',
+  'idle-detection=()',
+  'interest-cohort=()',
+  'magnetometer=()',
+  'microphone=()',
+  'midi=()',
+  'payment=()',
+  'publickey-credentials-get=()',
+  'screen-wake-lock=()',
+  'serial=()',
+  'usb=()',
+  'xr-spatial-tracking=()',
+].join(', ');
+
+const SECURITY_HEADERS = {
+  'Content-Security-Policy': CONTENT_SECURITY_POLICY,
+  'Permissions-Policy': PERMISSIONS_POLICY,
+  'Referrer-Policy': 'same-origin',
+  'Strict-Transport-Security': 'max-age=63072000; includeSubDomains',
+  'X-Content-Type-Options': 'nosniff',
+  'X-Frame-Options': 'DENY',
+  'X-DNS-Prefetch-Control': 'off',
+  'Cross-Origin-Opener-Policy': 'same-origin',
+  'Cross-Origin-Embedder-Policy': 'require-corp',
+  'Cross-Origin-Resource-Policy': 'same-origin',
+  'Origin-Agent-Cluster': '?1',
+  'X-Permitted-Cross-Domain-Policies': 'none',
+};
+
+function send(res, status, body, headers = {}) {
+  res.writeHead(status, {
+    ...SECURITY_HEADERS,
+    'Content-Type': 'text/plain; charset=utf-8',
+    'Cache-Control': 'no-store',
+    ...headers,
+  });
+  res.end(body);
+}
+
+// Map a URL path to a file inside ROOT, refusing traversal and hidden files.
+function resolvePath(pathname) {
+  let decoded;
+  try {
+    decoded = decodeURIComponent(pathname);
+  } catch {
+    return null;
+  }
+  if (decoded.includes('\0')) return null;
+  const segments = decoded.split('/').filter(Boolean);
+  if (segments.some((s) => s.startsWith('.') && s !== '.well-known')) return null;
+  const filePath = resolve(join(ROOT, ...segments));
+  if (filePath !== ROOT && !filePath.startsWith(ROOT + sep)) return null;
+  return filePath;
+}
+
+async function findFile(filePath) {
+  try {
+    const info = await stat(filePath);
+    if (info.isFile()) return { filePath, info };
+    if (info.isDirectory()) {
+      const index = join(filePath, 'index.html');
+      const indexInfo = await stat(index);
+      if (indexInfo.isFile()) return { filePath: index, info: indexInfo };
+    }
+  } catch {
+    // fall through to not found
+  }
+  return null;
+}
+
+const server = createServer(async (req, res) => {
+  const { pathname } = new URL(req.url, 'http://localhost');
+
+  // Logout: tell the browser to wipe everything this origin stored, then go home.
+  // Only POST, so links, prefetchers, and cross-site <img> tags can't trigger it.
+  if (pathname === '/logout') {
+    if (req.method !== 'POST') return send(res, 405, 'Method Not Allowed', { Allow: 'POST' });
+    return send(res, 303, '', {
+      Location: '/',
+      'Clear-Site-Data': '"cache", "cookies", "storage"',
+    });
+  }
+
+  if (req.method !== 'GET' && req.method !== 'HEAD') {
+    return send(res, 405, 'Method Not Allowed', { Allow: 'GET, HEAD' });
+  }
+
+  const filePath = resolvePath(pathname);
+  const found = filePath && (await findFile(filePath));
+  if (!found) return send(res, 404, 'Not Found');
+
+  const ext = extname(found.filePath).toLowerCase();
+  const isHtml = ext === '.html';
+  res.writeHead(200, {
+    ...SECURITY_HEADERS,
+    'Content-Type': MIME_TYPES[ext] || 'application/octet-stream',
+    'Content-Length': found.info.size,
+    // HTML is revalidated so header/policy changes apply immediately; static assets may be cached.
+    'Cache-Control': isHtml ? 'no-cache' : 'public, max-age=86400',
+    'Last-Modified': found.info.mtime.toUTCString(),
+  });
+  if (req.method === 'HEAD') return res.end();
+
+  createReadStream(found.filePath)
+    .on('error', () => res.destroy())
+    .pipe(res);
+});
+
+server.listen(PORT, HOST, () => {
+  console.log(`The Daily Grind serving ${ROOT} at http://${HOST}:${PORT}`);
+});

