+
+.newsletter-form {
+  max-width: 480px;
+  margin: 20px auto 0;
+  text-align: start;
+}
+
+.newsletter-form label {
+  display: block;
+  font-weight: 600;
+}
+
+.hint {
+  display: block;
+  color: #5d4037;
+  font-size: 0.85rem;
+  margin-bottom: 0.25rem;
+}
+
+.newsletter-row {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 10px;
+}
+
+.newsletter-row input {
+  flex: 1 1 220px;
+  font-size: 1rem;
+  min-height: 48px;
+  padding: 0.75rem;
+  border: 1px solid #8d6e63;
+  border-radius: 5px;
