+
+.newsletter-row .btn {
+  margin-top: 0;
+  min-height: 48px;
+  border: 0;
+  font: inherit;
+  cursor: pointer;
+}
+
+.newsletter-row .btn:disabled {
+  opacity: 0.7;
+  cursor: progress;
+}
+
+.error-msg {
+  display: none;
+  color: #b3261e;
+  font-size: 0.875rem;
+  margin-top: 0.25rem;
+}
+
+.newsletter-row input:user-invalid {
+  border-color: #b3261e;
+  background-color: #fce8e6;
+}
+
+.field:has(input:user-invalid) .error-msg {
+  display: block;
+}
+
+.form-status:empty {
+  display: none;
+}
+
+.form-status {
+  margin-top: 1rem;
+  padding: 0.75rem 1rem;
+  border-radius: 5px;
+  border-inline-start: 4px solid currentColor;
+}
+
+.form-status[data-state="success"] {
+  background: #e8f5e9;
+  color: #1b5e20;
+}
+
+.form-status[data-state="error"] {
+  background: #fce8e6;
+  color: #b3261e;
+}
+
+.form-status[data-state="pending"] {
+  background: var(--secondary);
+  color: var(--text);
+}
