+          window.removeEventListener('scroll', onScroll);
+          resolve();
+        };
+        const onScroll = () => {
+          clearTimeout(timeoutId);
+          timeoutId = setTimeout(finish, 100);
+        };
+        window.addEventListener('scrollend', finish, { once: true });
+        window.addEventListener('scroll', onScroll, { passive: true });
