+                <Fragment set:html={content} />
+            </div>
         </div>
+        {sections.length > 0 && (
+            <aside class="hidden lg:block w-56 shrink-0 order-first">
+                <nav data-section-nav aria-label="On this page" class="sticky top-6">
+                    <p class="text-xs font-semibold uppercase tracking-wide text-gray-500 mb-3">On this page</p>
+                    <ul class="border-l border-gray-200 text-sm">
+                        {sections.map(section => (
+                            <li>
+                                <a
+                                    href={`#${section.id}`}
+                                    class="block -ml-px border-l-2 border-transparent py-1.5 pl-4 text-gray-600 hover:text-gray-900 hover:border-gray-400 aria-[current=location]:border-amber-400 aria-[current=location]:text-gray-900 aria-[current=location]:font-semibold"
+                                >
+                                    {section.text}
+                                </a>
+                            </li>
+                        ))}
+                    </ul>
+                </nav>
+            </aside>
+        )}
