+<script>
+    // Highlight the section navigation link for the section currently in view
+    let controller: AbortController | undefined;
+
+    document.addEventListener('astro:page-load', () => {
+        controller?.abort();
+        const nav = document.querySelector<HTMLElement>('[data-section-nav]');
+        if (!nav) return;
+
+        controller = new AbortController();
+        const links = [...nav.querySelectorAll<HTMLAnchorElement>('a[href^="#"]')];
+        const headings = links
+            .map(link => document.getElementById(decodeURIComponent(link.hash.slice(1))))
+            .filter((heading): heading is HTMLElement => heading !== null);
+        if (headings.length === 0) return;
+
+        const update = () => {
+            // The active section is the last one whose heading has scrolled past the top third of the viewport
+            const threshold = window.innerHeight / 3;
+            const scrolledToBottom = window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 2;
+            let active = headings[0];
+            for (const heading of headings) {
+                if (heading.getBoundingClientRect().top <= threshold) active = heading;
+            }
+            if (scrolledToBottom) active = headings[headings.length - 1];
+
+            for (const link of links) {
+                if (link.hash === `#${active.id}`) {
+                    link.setAttribute('aria-current', 'location');
+                } else {
+                    link.removeAttribute('aria-current');
+                }
+            }
+        };
+
+        let frame = 0;
+        const onScroll = () => {
+            cancelAnimationFrame(frame);
+            frame = requestAnimationFrame(update);
+        };
+
+        window.addEventListener('scroll', onScroll, { passive: true, signal: controller.signal });
+        window.addEventListener('resize', onScroll, { passive: true, signal: controller.signal });
+        document.addEventListener('astro:before-swap', () => controller?.abort(), { once: true, signal: controller.signal });
+        update();
+    });
+</script>

