@@ -0,0 +1,100 @@
+import { createHash, randomInt, timingSafeEqual } from 'node:crypto';
+
+export const OTP_LENGTH = 6;
+export const OTP_TTL_MS = 5 * 60 * 1000;
+export const OTP_RESEND_COOLDOWN_MS = 30 * 1000;
+export const OTP_MAX_ATTEMPTS = 5;
+export const OTP_MAX_SENDS = 5;
+export const VERIFIED_PHONE_TTL_MS = 15 * 60 * 1000;
+
+export interface PendingOtp {
+  phone: string;
+  codeHash: string;
+  expiresAt: number;
+  lastSentAt: number;
+  sendCount: number;
+  attempts: number;
+}
+
+export interface VerifiedPhone {
+  phone: string;
+  verifiedAt: number;
+}
+
+/**
+ * Normalizes user input into E.164 (e.g. "+15551234567").
+ * Accepts spaces, dashes, dots and parentheses; requires a leading "+" country code.
+ */
+export function normalizePhone(input: unknown): string | null {
+  if (typeof input !== 'string') return null;
+  const trimmed = input.trim();
+  if (!trimmed.startsWith('+')) return null;
+  const digits = trimmed.slice(1).replace(/[\s().-]/g, '');
+  if (!/^[1-9]\d{7,14}$/.test(digits)) return null;
+  return `+${digits}`;
+}
+
+export function maskPhone(phone: string): string {
+  return phone.length <= 4 ? phone : `${phone.slice(0, -4).replace(/\d/g, '•')}${phone.slice(-4)}`;
+}
+
+export function generateOtp(): string {
+  return randomInt(0, 10 ** OTP_LENGTH).toString().padStart(OTP_LENGTH, '0');
+}
+
+export function hashOtp(phone: string, code: string): string {
+  return createHash('sha256').update(`${phone}:${code}`).digest('hex');
+}
+
+export function otpMatches(pending: PendingOtp, code: string): boolean {
+  const expected = Buffer.from(pending.codeHash, 'hex');
+  const actual = Buffer.from(hashOtp(pending.phone, code), 'hex');
+  return expected.length === actual.length && timingSafeEqual(expected, actual);
+}
+
+/**
+ * Builds an SMS body compatible with the WebOTP API. The final line must be
+ * "@<host> #<code>" where host matches the origin of the page requesting the code.
+ * https://wicg.github.io/web-otp/#web-otp-message-format
+ */
+export function formatOtpMessage(code: string, host: string): string {
+  return `${code} is your DevTools Times verification code. It expires in ${OTP_TTL_MS / 60000} minutes.\n\n@${host} #${code}`;
+}
+
+/**
+ * Delivers an SMS. Uses Twilio when TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN and
+ * TWILIO_FROM_NUMBER are configured; otherwise logs the message (development only).
+ */
+export async function sendSms(to: string, body: string): Promise<void> {
+  const sid = process.env.TWILIO_ACCOUNT_SID;
+  const token = process.env.TWILIO_AUTH_TOKEN;
+  const from = process.env.TWILIO_FROM_NUMBER;
+
+  if (!sid || !token || !from) {
+    if (import.meta.env.PROD) {
+      throw new Error('SMS provider is not configured');
+    }
+    console.info(`[sms:dev] to ${to}:\n${body}`);
+    return;
+  }
+
+  const response = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${sid}/Messages.json`, {
+    method: 'POST',
+    headers: {
+      Authorization: `Basic ${Buffer.from(`${sid}:${token}`).toString('base64')}`,
+      'Content-Type': 'application/x-www-form-urlencoded',
+    },
+    body: new URLSearchParams({ To: to, From: from, Body: body }),
+  });
+
+  if (!response.ok) {
+    throw new Error(`SMS provider responded with ${response.status}`);
+  }
+}
+
+export function json(data: unknown, status = 200, headers: Record<string, string> = {}): Response {
+  return new Response(JSON.stringify(data), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...headers },
+  });
+}

