+        let seconds = ns / NS_PER_SECOND;
+        let fraction = ns % NS_PER_SECOND;
+        if (fraction < 0n) { fraction += NS_PER_SECOND; seconds -= 1n; }
+        const base = new Date(Number(seconds) * 1000).toISOString().slice(0, 19);
+        return base + '.' + fraction.toString().padStart(9, '0') + 'Z';
+      }
+
+      // Exact decimal rendering of a nanosecond duration in the most readable unit.
+      function formatDurationNs(ns) {
