+    --_fg: var(--site-nav-fg, white);
+    --_accent: var(--site-nav-accent, var(--accent, #ffab40));
+
+    display: block;
+    position: sticky;
+    top: 0;
+    z-index: 1000;
+    container-type: inline-size;
+    background: var(--_bg);
+    color: var(--_fg);
+  }
+
+  *, *::before, *::after {
+    box-sizing: border-box;
+  }
+
+  nav {
