+    background: var(--secondary, #d7ccc8);
+  }
+
+  .media img {
+    display: block;
+    width: 100%;
+    height: 100%;
+    object-fit: cover;
+  }
+
+  .body {
+    display: flex;
+    flex: 1;
+    flex-direction: column;
+    align-items: center;
+    padding: 20px;
+  }
+
+  ::slotted([slot="title"]) {
+    margin: 0 0 10px;
+    color: var(--primary, #4e342e);
+    font-size: 1.17em;
+  }
+
+  ::slotted(:not([slot])) {
+    margin: 0;
+  }
+
+  .actions {
+    margin-top: auto;
+  }
+`);
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <div class="media" part="media" hidden>
+    <img alt="" loading="lazy" decoding="async">
+  </div>
+  <div class="body" part="body">
+    <slot name="title"></slot>
